(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c37"]=[{"id":"00016431","register_sub_id":"101","register_pk":"536498","name":"蓮華定院塀","kana":"れんげじょういんへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字一心院谷700","lat":34.21789444,"lng":135.58147222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、檜皮葺、延長40m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0418","desc":"山門の西側に続く折曲延長40メートルの檜皮葺の塀。柱を一間毎に立て、壁は真壁とし、腰は外を海鼠壁で上部に水切を付す。内は竪板張とする。中央東寄りに通用口を開け、片引板戸を建てる。通りに面して海鼠壁が連なり、重厚な外観が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016431"},{"id":"00016428","register_sub_id":"101","register_pk":"536495","name":"蓮華定院本堂及び護摩堂","kana":"れんげじょういんほんどうおよびごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山700","lat":34.21808889,"lng":135.58129444,"geo_status":"db","era":"万延元年（1860）／昭和48年増築","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"土蔵造一部木造平屋建、檜皮葺一部金属板葺、建築面積242㎡","structure_material":"土蔵造一部木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0415","desc":"一心院谷の東北側に位置する真言宗寺院の仏堂。境内南西端に東面して建つ、入母屋造平入檜皮葺の本堂の北に棟を切下げ護摩堂を接続し、本堂正面に一間向拝を付す。天保14年大火後の再建で、外壁は漆喰塗仕上の大壁で堅牢につくり、独特な外観を呈する仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016428"},{"id":"00007762","register_sub_id":"101","register_pk":"108743","name":"網野神社石鳥居","kana":"あみのじんじゃいしとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68305085,"lng":135.0270127,"geo_status":"db","era":"明治14／大正後期移築・昭和4改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"石造、高さ5.5m、幅4.4m","structure_material":"石造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0341","desc":"境内南辺の中央に位置し、本殿への参道が北へ延びる。石造の明神鳥居。高さ５．５ｍ、幅４．４ｍ。低い亀腹上に、直径０．４６ｍの円柱を内転びに建て、貫で固め、反り増しのある笠木と島木を置く。伝統的な比例を踏襲し、安定した姿を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007762"},{"id":"00007760","register_sub_id":"101","register_pk":"108741","name":"網野神社境内社蠶織神社本殿","kana":"あみのじんじゃけいだいしゃこおりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68344082,"lng":135.02749305,"geo_status":"db","era":"天明2／大正13・昭和38改修","year":1782,"year_source":"db","year_min":1782,"year_max":1782,"year_label":null,"structure":"木造、檜皮葺、建築面積7.6㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0339","desc":"境内の東寄りに西面して建つ。檜皮葺の一間社流造、三方に組高欄付切目縁をまわす。柱は円柱で、本支輪付出組とし、桁と妻虹梁を持ち出す。二軒繁垂木で、妻は笈形付虹梁大瓶束。正面に双折両開桟唐戸を吊る。向拝や身舎中備、脇障子など要所に彫物を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007760"},{"id":"00007758","register_sub_id":"101","register_pk":"108739","name":"網野神社神饌所","kana":"あみのじんじゃしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68388964,"lng":135.02699645,"geo_status":"db","era":"昭和前期／平成20改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、金属板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0337","desc":"拝殿北面の西端に建つ。桁行二間梁間二間、南北棟の切妻造金属板葺。面取方柱を長押で固め、柱上に舟肘木を置く。一軒疎垂木で、妻は虹梁蟇股。正面に妻戸、東面に蔀などを装置し、横板壁で、上部に横連子や竪連子窓を開ける。緩い勾配の優美な屋根になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007758"},{"id":"00007759","register_sub_id":"101","register_pk":"108740","name":"網野神社透塀","kana":"あみのじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68397644,"lng":135.02711914,"geo_status":"db","era":"昭和前期／平成20改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、金属板葺、延長30m","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0338","desc":"拝殿後方から本殿を囲んで建つ。延長３０ｍ。方柱を長押等で固め、腕木が軒桁を支持。一軒疎垂木で切妻造金属板葺。腰を横板壁とし、上部に菱格子を嵌め、東西各１ヵ所に両開戸を構える。本殿背面は切石積上に屋根のない瑞垣とする。本殿まわりを厳粛に結界する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007759"},{"id":"00007761","register_sub_id":"101","register_pk":"108742","name":"網野神社手水舎","kana":"あみのじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68312954,"lng":135.02695919,"geo_status":"db","era":"昭和18／平成4改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造、銅板葺、面積6.1㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0340","desc":"境内の南寄り、参道の脇に位置する。桁行一間梁間一間で周囲を吹き放つ。南北棟の切妻造銅板葺。大きく面を取る方柱を切石礎石上に建て、内法貫で固める。柱上に舟肘木を置き、桁や梁を支持。一軒疎垂木の化粧屋根裏天井。妻に蟇股を置く。軸太な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007761"},{"id":"00007756","register_sub_id":"101","register_pk":"108737","name":"網野神社拝殿","kana":"あみのじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68376981,"lng":135.02709765,"geo_status":"db","era":"昭和4／平成20改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0335","desc":"本殿の南方に建つ。桁行三間梁間二間で四周に高欄付切目縁をまわす。入母屋造金属板葺、正面に千鳥破風と唐破風を付ける。側まわりに蔀を装置。内部は拭板敷で、折上小組格天井を張る。柱間の中央に大きく広がる蟇股を置き、左右対称の唐草模様で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007756"},{"id":"00007755","register_sub_id":"101","register_pk":"108736","name":"網野神社本殿","kana":"あみのじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68391481,"lng":135.02711412,"geo_status":"db","era":"大正11／平成20改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0334","desc":"境内中央に位置する。一間社流造金属板葺で、二重基壇上に建つ。円柱で三斗組。組高欄付縁を三方にめぐらし、脇障子を構える。身舎正面は吹寄せ格子の板戸四枚引違をたて、他を板壁とする。蟇股や木鼻、絵様など古建築に精通した設計者ならではの意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007755"},{"id":"00007757","register_sub_id":"101","register_pk":"108738","name":"網野神社渡廊","kana":"あみのじんじゃわたろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68385041,"lng":135.02710746,"geo_status":"db","era":"昭和4頃／平成20改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0336","desc":"本殿と拝殿の間に建つ。桁行二間梁間一間、南北棟の切妻造妻入金属板葺。面取方柱で、舟肘木を置き、軒は一軒疎垂木。両側面に蔀戸を装置。拭板敷で、化粧屋根裏天井。梁行に虹梁を架し、蟇股を飾る。薄い舟肘木や垂木の反りなど繊細な意匠感覚が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007757"},{"id":"00003265","register_sub_id":"101","register_pk":"104255","name":"安楽寺山門","kana":"あんらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区鹿ケ谷御所ノ段町21","lat":35.02135008,"lng":135.7962735,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、茅葺、間口2.2m、袖塀付","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0148","desc":"寺地南西隅の緩い石段を上がったところに西面して建つ。八角円柱の本柱と面皮の控柱を立て，丸太の桁を回し，小丸太の垂木を扇に配して軒を構成し，屋根を寄棟造，茅葺とする。数寄屋風の造りで特徴ある彫物を付すなど景観構成上欠かせない意匠を凝らした門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003265"},{"id":"00003264","register_sub_id":"101","register_pk":"104254","name":"安楽寺書院（客殿）","kana":"あんらくじしょいん（きゃくでん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区鹿ケ谷御所ノ段町21","lat":35.02158643,"lng":135.79673938,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0147","desc":"本堂の東に位置し，渡廊下で連絡する。桁行約１３．７ｍ，梁間約７ｍ，切妻造，桟瓦葺で，南に下屋を付す。南北に３室を並べ（もとは１５畳２室），東西及び南に縁を回す。奥の主室には床・違棚を備え，丸太や色土壁を用いて，簡素だが数寄屋風の座敷に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003264"},{"id":"00003263","register_sub_id":"101","register_pk":"104253","name":"安楽寺本堂","kana":"あんらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区鹿ケ谷御所ノ段町21","lat":35.02161306,"lng":135.79655807,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0146","desc":"本堂は境内北寄りに南面して建つ。一重，宝形造，本瓦葺，裳階付の前堂の背後に，後設の切妻造，桟瓦葺の正堂を張り出す。前堂は方１間格天井の身舎周囲に化粧屋根裏の庇を回した形式で，正堂は鏡天井で須弥壇を構える。江戸後期浄土宗本堂の展開を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003263"},{"id":"00013595","register_sub_id":"101","register_pk":"504958","name":"出雲大神宮石鳥居","kana":"いずもだいじんぐういしとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05880833,"lng":135.57827222,"geo_status":"db","era":"享保3年(1718)","year":1718,"year_source":"db","year_min":1718,"year_max":1718,"year_label":null,"structure":"石造、間口4.8m","structure_material":"石造","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0623","desc":"参道屈曲部北側の低い石段上に建つ、花崗岩製の明神鳥居。直径五七センチメートルの円柱を間口四・八メートルに立て、貫で固め、島木、笠木を渡す。島木と笠木は両者全長を一材から造り出す。氏子の寄進により建立された、良材による堅実な作りの石鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013595"},{"id":"00013597","register_sub_id":"101","register_pk":"504960","name":"出雲大神宮上之社本殿","kana":"いずもだいじんぐうかみのやしろほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05949167,"lng":135.57920278,"geo_status":"db","era":"文化10年(1813)","year":1813,"year_source":"db","year_min":1813,"year_max":1813,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0625","desc":"本殿東方の山中に建つ一間社流造、前室及び向拝付、鉄板葺。三方に縁高欄を廻らし身舎の棟通に脇障子をたて正面に木階を付す。前室の庇部は正面に格子、側面に連子窓を建てた外陣とし、身舎は内陣と内々陣に画す。本殿の独自形式に倣いつつ縮小した境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013597"},{"id":"00013593","register_sub_id":"101","register_pk":"504956","name":"出雲大神宮祭器庫","kana":"いずもだいじんぐうさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05881667,"lng":135.578575,"geo_status":"db","era":"明治18年／大正7年移築","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0621","desc":"参道東方の一段高い場所に南北棟で建ち、土蔵造二階建、寄棟造鉄板葺。西面中央を戸口として土戸両開きとし、下屋を設ける。二階の両妻に小窓を穿ち、庇の持送に彫刻を施す。外壁漆喰塗で腰を海鼠壁、軒に蛇腹を廻らす。素木造主体の境内に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013593"},{"id":"00013592","register_sub_id":"101","register_pk":"504955","name":"出雲大神宮社務所","kana":"いずもだいじんぐうしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05891667,"lng":135.57813333,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0620","desc":"拝殿前方の参道西方に建つ。東西棟の入母屋造の北側に折曲がりに角屋を張出し、西側にも張出しをもつ桟瓦葺建物で変化ある外観とする。平面は座敷列を雁行配置して高欄付縁を廻らし、舞良戸をたて、小壁の蟇股に菊花紋をあしらう。重厚で気品を備えた社務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013592"},{"id":"00013590","register_sub_id":"101","register_pk":"504953","name":"出雲大神宮神饌所","kana":"いずもだいじんぐうしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05928611,"lng":135.57815,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0618","desc":"中門西方に南北棟で建ち、桁行一〇メートル、入母屋造鉄板葺。角柱に舟肘木を載せ、東正面中央間の出入口に板唐戸を開き、欄間に吹寄菱格子を入れる。内部は三室で南室は床棚付の座敷、北室は板敷の神饌所で井戸をもつ。神官控所を備えた端正な意匠の神饌所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013590"},{"id":"00013596","register_sub_id":"101","register_pk":"504959","name":"出雲大神宮制札","kana":"いずもだいじんぐうせいさつ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05878333,"lng":135.57821111,"geo_status":"db","era":"明治6年","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造、銅板葺、間口0.9m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0624","desc":"石鳥居の手前西側に東西棟で建つ。花崗岩切石積の基壇上に角柱二本を間口〇・九メートルに立てて貫で固める。柱上部の腕木で桁を受け、わずかに反りを持たせた垂木を疎らに配り、切妻造、段葺状の銅板葺とする。境内の近代再興最初期の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013596"},{"id":"00013598","register_sub_id":"101","register_pk":"504961","name":"出雲大神宮摂社黒太夫社","kana":"いずもだいじんぐうせっしゃくろだゆうしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳南所44","lat":35.05981944,"lng":135.57673056,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.3㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0626","desc":"境内から約一〇〇メートル西方に所在する境外社。南面する一間社流造、鉄板葺で、三方に刎高欄付の縁を廻らせ、背面柱筋に脇障子をたて、庇に浜縁を張る。軸部や組物等の大面取、蟇股や手挟など細部に古典意匠の習熟が看取される。戦前の復古調社殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013598"},{"id":"00013591","register_sub_id":"101","register_pk":"504954","name":"出雲大神宮奏楽舎","kana":"いずもだいじんぐうそうがくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05923333,"lng":135.57860556,"geo_status":"db","era":"明治14年／明治41年移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0619","desc":"中門東方の一段高い石垣上に東西棟で建ち、入母屋造鉄板葺である。内部は床と床脇を備えた一室で、南面と西面に高欄付の切目縁を廻らし、軒は一軒疎垂木。はじめ神饌所として建てられ、現神饌所新築の際に移築された。境内の変遷経過を伝える意匠簡明な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013591"},{"id":"00013594","register_sub_id":"101","register_pk":"504957","name":"出雲大神宮手水舎","kana":"いずもだいじんぐうてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05888056,"lng":135.57837222,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造、瓦葺、面積6.2㎡","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0622","desc":"参道の東側に社務所と相対して南北棟で建つ。桁行一間梁間一間、長方形平面の吹放し形式で、起り付きの切妻造桟瓦葺。礎盤上に四本柱を内転びに立て、西面に虹梁形内法貫を渡し、他の三面は貫で固め、柱天に舟肘木を組む。境内入口の景観に寄与する手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013594"},{"id":"00013589","register_sub_id":"101","register_pk":"504952","name":"出雲大神宮拝殿","kana":"いずもだいじんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05915833,"lng":135.57835278,"geo_status":"db","era":"明治11年","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0617","desc":"中門前方に建つ南北棟、桁行三間梁間三間、入母屋造檜皮葺、四方吹放し形式の拝殿。亀腹上に円柱を立て、周囲に刎高欄付の縁を廻らし、内部は全面小組格天井張、軒は二軒繁垂木として軽やかな軒反りをもたせる。境内中枢を占め、格式と優美さを備えた拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013589"},{"id":"00013588","register_sub_id":"101","register_pk":"504951","name":"出雲大神宮本殿廻廊及び透塀","kana":"いずもだいじんぐうほんでんかいろうおよびすきべい","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05926667,"lng":135.57849167,"geo_status":"db","era":"廻廊 昭和10年、透塀 明治26年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"廻廊 木造平屋建、檜皮葺、建築面積37㎡ 透塀 木造、鉄板葺、総延長41m","structure_material":"廻廊 木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0616","desc":"中門の東西にのびる廻廊と、その両端から北に廻る透塀。廻廊は桁行四間で外側は角柱に長押を廻らし、各間に連子窓を入れる。内側は吹放しで梁行に虹梁を架ける。透塀も廻廊と同様の立面として調和を図る。本殿の神域を囲繞する落着いた佇まいの廻廊と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013588"},{"id":"00013587","register_sub_id":"101","register_pk":"504950","name":"出雲大神宮本殿中門及び祝詞舎","kana":"いずもだいじんぐうほんでんちゅうもんおよびのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05927778,"lng":135.57836389,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0615","desc":"拝殿背後に建つ中門の背面に祝詞舎を接続し、拝殿、祝詞舎後方の本殿とともに主要社殿の中軸をなす。中門は四脚門、祝詞舎は中門の背面柱を共有した桁行二間の吹放し形式で、本殿側に軒唐破風を付け、総檜皮葺。和様を基調とし復古的細部を用いた礼拝施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013587"},{"id":"00012184","register_sub_id":"101","register_pk":"352984","name":"今宮神社疫神社本殿","kana":"いまみやじんじゃえきじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.046017,"lng":135.741844,"geo_status":"db","era":"明治41年頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-532","desc":"本殿の西側に並び建ち、桁行三間梁間二間、入母屋造、向拝一間、銅板葺。正側面に刎高欄付の切目縁を廻らして脇障子をたて、外陣に板唐戸と蔀をたてる。蟇股などに、中世社寺の細部の近代的表現による優美な意匠が用いられる。亀岡の特質を示す良質な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012184"},{"id":"00012185","register_sub_id":"101","register_pk":"352985","name":"今宮神社疫神社渡廊・門・廻廊","kana":"いまみやじんじゃえきじんじゃわたろう・もん・かいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04592,"lng":135.741825,"geo_status":"db","era":"明治41年頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-533","desc":"疫神社本殿前に切妻造妻入の渡廊を建てて前面に平唐門を開き、その左右に廻廊をのばす。渡廊は桁行の横架材に反りをもたせて廊全体を強く反らせる。廻廊は前面柱間に吹寄菱欄間を入れる。渡廊、門とも蟇股や門の透彫欄間など亀岡らしい繊細優美な意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012185"},{"id":"00012189","register_sub_id":"101","register_pk":"352989","name":"今宮神社絵馬舎","kana":"いまみやじんじゃえましゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045268,"lng":135.741831,"geo_status":"db","era":"寛政12年(1800)","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-537","desc":"境内南西隅に南北棟で建ち、周囲を吹放す形式で、桁行六間梁間二間、入母屋造桟瓦葺である。基壇上に建ち、太めの角柱を貫で固め、舟肘木で桁を受け、軒は一軒疎垂木、妻飾は虹梁大瓶束とする。内外に多数の絵馬を掲げ、当社の庶民信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012189"},{"id":"00012213","register_sub_id":"101","register_pk":"353013","name":"今宮神社御旅所鏡の間","kana":"いまみやじんじゃおたびしょかがみのま","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039286,"lng":135.748912,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-561","desc":"境内西端に南北棟で建ち、能舞台の橋掛に接続する。桁行一〇・一メートル梁間三・九メートル、入母屋造桟瓦葺。外壁は真壁で中塗仕上とし、東面の橋掛取付部に覗き窓を設ける。内部は広間など三室からなる。能舞台と一体の施設として御旅所の構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012213"},{"id":"00012210","register_sub_id":"101","register_pk":"353010","name":"今宮神社御旅所権殿社","kana":"いまみやじんじゃおたびしょごんでんしゃ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039286,"lng":135.749246,"geo_status":"db","era":"寛政7年(1795)","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積8.9㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-558","desc":"境内北東寄りに南面し、前面に神輿奉安殿を建てる。三間社入母屋造、一間向拝付で、正側面に切目縁を廻らす。組物は三斗で中備蟇股とする。旧洛中の最北に位置し、今宮祭の際に神輿から祭神が遷座する重要な役割を担う社殿で、細部意匠はよく整っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012210"},{"id":"00012211","register_sub_id":"101","register_pk":null,"name":"今宮神社御旅所神輿奉安殿","kana":"いまみやじんじゃおたびしょしんよほうあんでん","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039202,"lng":135.749236,"geo_status":"db","era":"昭和20年","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-559","desc":"殿社前面に建ち、桁行一〇・五メートル梁間八・六メートル、入母屋造鉄板葺。各面三間で小壁の下方を吹放ちとする。正背面中央間を広め、楣を高く納めて神輿の出入りの便を図る。内部は格天井で、小屋はトラス組。御旅所の中核をなす規模の大きな奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012211"},{"id":"00012212","register_sub_id":"101","register_pk":"353012","name":"今宮神社御旅所能舞台","kana":"いまみやじんじゃおたびしょのうぶたい","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039198,"lng":135.749092,"geo_status":"db","era":"寛政7年(1795)","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-560","desc":"神輿奉安殿の西隣に南面する。桁行梁間とも五・九メートル、入母屋造妻入で、背面に後座を設けて鏡板に松と竹を描き、東面軒下の切目縁を謡座とする。後座西端と鏡の間の間に橋掛を渡す。舞台背面に虹梁を架け、小組格天井を張る。近世能舞台の古例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012212"},{"id":"00012186","register_sub_id":"101","register_pk":"352986","name":"今宮神社神楽殿","kana":"いまみやじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045977,"lng":135.742235,"geo_status":"db","era":"天保10年(1839)／明治後期改修","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-534","desc":"本殿東側に南北棟で建ち、渡廊で本殿とつなぐ。桁行六・九メートル梁間三・九メートルの神楽所の北室を神殿とし、全体を入母屋造銅板葺とする。神楽所は開放的なつくりで柱上に舟肘木をおき、南室に格天井を張り、切目縁を廻らす。繊細な意匠の神楽殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012186"},{"id":"00012202","register_sub_id":"101","register_pk":"353002","name":"今宮神社祭器庫","kana":"いまみやじんじゃさいきこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045998,"lng":135.742393,"geo_status":"db","era":"江戸後期／大正後期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-550","desc":"境内北東隅に南北棟で建ち、桁行三間梁間三間、切妻造桟瓦葺。正面中央の柱間をやや広め、中間を竪連子とする桟唐戸を両開きとする。外壁は真壁造で見せ貫とし、妻壁は梁上に大振りの蟇股を置き、虹梁と豕扠首を組む。境内後方の歴史的景観に寄与する祭器庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012202"},{"id":"00012194","register_sub_id":"101","register_pk":"352994","name":"今宮神社地主社拝所・透塀","kana":"いまみやじんじゃじしゅしゃはいしょ・すきべい","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045583,"lng":135.741681,"geo_status":"db","era":"天保13年(1842)","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"拝所 木造平屋建、銅板葺、建築面積6.0㎡ 透塀 木造、総延長6.0m","structure_material":"拝所 木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-542","desc":"地主社本殿正面に建つ拝所と左右の透塀。拝所は桁行二間梁間一間、切妻造妻入で、桁行中央の柱間を結界として吹寄菱格子の扉を両開とする。透塀は拝所桁行中央柱と同じ切石積基礎に建ち、各間に格子をたて目板瓦を葺く。独特の礼拝空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012194"},{"id":"00012193","register_sub_id":"101","register_pk":"352993","name":"今宮神社地主社本殿","kana":"いまみやじんじゃじしゅしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045596,"lng":135.741681,"geo_status":"db","era":"天保13年(1842)","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.7㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-541","desc":"境内西側、若宮社裏の微高地に南面し、二間社流造、銅板葺。周囲に刎高欄付の縁を廻らし、隅行の三手先腰組で支持する。庇は総桁行を一間とし向拝柱に虹梁形頭貫を渡し、蟇股二個をおき、身舎柱と海老虹梁で繋ぐ。間口二間の身舎、縁腰組に独自性を示す社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012193"},{"id":"00012203","register_sub_id":"101","register_pk":"353003","name":"今宮神社神輿庫","kana":"いまみやじんじゃしんよこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045417,"lng":135.742554,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、建築面積80㎡","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-551","desc":"東門の北側に南北棟で建つ。桁行一二・一メートル梁間六・六メートル、土蔵造、寄棟造桟瓦葺で、軒蛇腹を廻らす。西正面は神輿の出入りのため広い柱間で三区画し、黒色の大きな鉄扉を開き、庇を通す。内部は一室で床張とする。重厚な外観をもつ大型の神輿庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012203"},{"id":"00012199","register_sub_id":"101","register_pk":"352999","name":"今宮神社大将軍社本殿・拝所","kana":"いまみやじんじゃたいしょうぐんしゃほんでん・はいしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04558,"lng":135.741763,"geo_status":"db","era":"元禄8年(1695)頃","year":1695,"year_source":"db","year_min":1695,"year_max":1695,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-547","desc":"境内西寄り、八幡社と日吉社の間に東面して建つ。一間社流見世棚造の本殿の前面に、方一間、切妻造妻入の拝所を接続し、拝所背面に設けた棚と本殿の間に木階三級を付けるという独特な形式をもつ。拝所は吹放ち形式で、柱上部の繰型付の持送りも特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012199"},{"id":"00012196","register_sub_id":"101","register_pk":"352996","name":"今宮神社月読社拝所・透塀","kana":"いまみやじんじゃつくよみしゃはいしょ・すきべい","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04540894,"lng":135.74160218,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"拝所 木造平屋建、瓦葺、建築面積2.8㎡ 透塀 木造、瓦葺、総延長5.8m","structure_material":"拝所 木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-544","desc":"月読社本殿正面の切石積基壇に建つ拝所と左右の透塀。拝所は方一間、切妻造妻入で背面柱筋に格子を入れて結界とする。角柱上の舟肘木で虹梁と桁を受け、両妻に豕扠首を組む。透塀は目板瓦葺で柱間に木柵を設ける。境内中心から隔された静かな佇まいの社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012196"},{"id":"00012195","register_sub_id":"101","register_pk":"352995","name":"今宮神社月読社本殿","kana":"いまみやじんじゃつくよみしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045393,"lng":135.741543,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-543","desc":"境内西方の石段上に東面して建ち、一間社流造、銅板葺である。正側面に刎高欄付切目縁を廻らして脇障子をたて、庇に浜床と浜縁を設ける。身舎、庇とも柱上に舟肘木をおく。庇柱は柱天より下方に虹梁を架けて蟇股を置く特異な形式をもつ。簡明な意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012195"},{"id":"00012204","register_sub_id":"101","register_pk":"353004","name":"今宮神社手水舎","kana":"いまみやじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045215,"lng":135.742336,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造、瓦葺、面積5.9㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"26-552","desc":"楼門の北東に位置して北向きに建ち、東参道参詣者の便を図る。方一間、入母屋造で、角柱を貫で固めて各面に格子をたてる。内法貫上に二個、頭貫上に一個の蟇股を置き、いずれも実肘木を一体化して繰型を施す異形の中備とする。華やかな細部意匠をもつ手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012204"},{"id":"00012188","register_sub_id":"101","register_pk":"352988","name":"今宮神社拝殿","kana":"いまみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045708,"lng":135.742059,"geo_status":"db","era":"元禄7年(1694)／弘化3年(1846)改修","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-536","desc":"幣殿正面に東西棟で建つ。桁行三間梁間三間、入母屋造銅板葺で、桁行中央間を約二間分と広め、周囲に刎高欄付切目縁を廻らす。柱上に舟肘木をおき格天井を張り、軒は二軒疎垂木で妻飾を木連格子とする。境内軸の中枢をなす比較的規模の大きな舞殿形式の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012188"},{"id":"00012198","register_sub_id":"101","register_pk":"352998","name":"今宮神社八幡社","kana":"いまみやじんじゃはちまんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04559,"lng":135.741763,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-546","desc":"境内西寄り、八社の南側に東面して建ち、一間社流造、銅板葺。正側面に刎高欄付切目縁を廻らし、脇障子をたてる。身舎は付柱と板唐戸で前後に二分し、前寄りを吹放す。庇組物の桁行肘木は内方も伸ばして虹梁形頭貫上の斗で受ける。手の込んだ造作の境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012198"},{"id":"00012197","register_sub_id":"101","register_pk":"352997","name":"今宮神社八社","kana":"いまみやじんじゃはっしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045644,"lng":135.741765,"geo_status":"db","era":"元禄7年(1694)頃","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.5㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-545","desc":"若宮社の北側に並ぶ小社群の北端に建つ。八間社流見世棚造、桟瓦葺で、各間に八幡神等を祀り、庇は一間おきに柱を省く。身舎は円柱、庇は角柱として舟肘木をおき、庇の梁行を虹梁で繋ぐ。元禄再興期に末社を合祀して建立されたとされ、境内再編履歴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012197"},{"id":"00012209","register_sub_id":"101","register_pk":"353009","name":"今宮神社東門南北築地塀","kana":"いまみやじんじゃひがしもんなんぼくついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045141,"lng":135.742597,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土塀、瓦葺、延長27m","structure_material":"土塀","registered":"2018.03.27(平成30.03.27)","register_no":"26-557","desc":"東門の南北に折曲がりにのびる土塀で、切妻造本瓦葺である。切石積基礎に布石を伏せて須柱を立て、桁上の出し梁で軒桁を受け、一軒繁垂木の軒を受ける。壁は中塗仕上げで定規筋五本を現す。妻には蟇股を置くなど上質なつくりで、門前の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012209"},{"id":"00012200","register_sub_id":"101","register_pk":"353000","name":"今宮神社日吉社","kana":"いまみやじんじゃひよししゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045568,"lng":135.741762,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.6㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-548","desc":"若宮社北側の小社群の南端に東面して建つ。一間社流見世棚造、銅板葺。身舎内部を前後に二分して室境に板唐戸を開き、前室前面に格子をたてる。身舎は円柱に舟肘木をおき、庇は角柱上の連三斗で桁を受け、中備蟇股とする。境内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012200"},{"id":"00012183","register_sub_id":"101","register_pk":"352983","name":"今宮神社幣殿・拝所・廻廊","kana":"いまみやじんじゃへいでん・はいしょ・かいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045916,"lng":135.742044,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-531","desc":"本殿前に切妻造妻入の幣殿を建てて前面に向唐破風造の拝所を構え、幣殿左右に廻廊をのばす。いずれも円柱で、幣殿は柱を絵様虹梁で繋ぎ大斗実肘木を載せ、廻廊は舟肘木で桁を受け、前面柱間に吹寄菱欄間を入れる。拝所妻壁は透彫の雲紋等で装飾性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012183"},{"id":"00012182","register_sub_id":"101","register_pk":"352982","name":"今宮神社本殿","kana":"いまみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.046014,"lng":135.742039,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-530","desc":"境内北端に疫神社本殿と並び建つ。桁行三間梁間二間、切妻造、向拝一間、銅板葺。四周に榑縁を廻らし脇障子をたて、外陣に板唐戸と蔀をたてる。向拝の間口と奥行、けらばを広めて屋根をのびやかに張出す。伝統形式を保守しつつ優美な外観をもつ近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012182"},{"id":"00012187","register_sub_id":"101","register_pk":"352987","name":"今宮神社本殿築地塀","kana":"いまみやじんじゃほんでんついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.046087,"lng":135.741719,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、延長65m","structure_material":"土塀","registered":"2018.03.27(平成30.03.27)","register_no":"26-535","desc":"本殿と疫神社本殿の北背面と東西両面に折曲がりに廻らされた土塀で、延長六五・四メートルを測る。北面中央に埋門を設け、切妻造桟瓦葺及び本瓦葺である。石積基礎上に建ち、内側は一間毎に須柱を立て、定規筋五本を現す。本殿域に格式を添える上質な土塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012187"},{"id":"00012201","register_sub_id":"101","register_pk":"353001","name":"今宮神社宗像社","kana":"いまみやじんじゃむなかたしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045174,"lng":135.742424,"geo_status":"db","era":"元禄7年(1694)頃","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-549","desc":"境内南東隅に東面し、鯰を陰刻した切石積基壇に建ち、一間社流造、銅板葺である。身舎前半を吹放ち、正側面に縁を廻らし脇障子をたて庇に浜床を付ける。身舎は円柱に舟肘木、庇は角柱に三斗を組み、両者を海老虹梁で繋ぐ。小社ながら多様な造作が施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012201"},{"id":"00012205","register_sub_id":"101","register_pk":"353005","name":"今宮神社楼門","kana":"いまみやじんじゃろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045134,"lng":135.742185,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、銅板葺、建築面積47㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"26-553","desc":"境内南正面の中ほどに建つ。三間一戸楼門、入母屋造銅板葺。下層は腰組を三手先とし、脚を伸ばした華麗な蟇股を配し、上層は尾垂木付三手先を組み、間斗束をおく。柱間の逓減、階高の調整により安定感のある姿形をもち、細部には近代社寺建築の特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012205"},{"id":"00012207","register_sub_id":"101","register_pk":"353007","name":"今宮神社楼門西廻廊","kana":"いまみやじんじゃろうもんにしかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045118,"lng":135.742069,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-555","desc":"楼門の西にやや間をあけて東西棟で建つ。桁行三間梁間一間、切妻造本瓦葺である。正背面に連子窓、両妻に板唐戸をたて、中備の間斗束に舟肘木を載せる。隅柱を延ばし、二軒の軒や妻の破風に強い反りをもたせる。中世以前の意匠、技法を援用した良質な廻廊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012207"},{"id":"00012206","register_sub_id":"101","register_pk":"353006","name":"今宮神社楼門東廻廊","kana":"いまみやじんじゃろうもんひがしかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04514,"lng":135.742334,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-554","desc":"楼門の東にやや間をあけて東西棟で建つ。桁行三間梁間一間、切妻造本瓦葺である。正背面に連子窓、両妻に板唐戸をたて、中備の間斗束に舟肘木を載せる。妻飾は虹梁上に蟇股、大斗、出三斗を組み、細部彫刻に中世以前の意匠を援用した良質な廻廊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012206"},{"id":"00012191","register_sub_id":"101","register_pk":"352991","name":"今宮神社若宮社拝殿","kana":"いまみやじんじゃわかみやしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045491,"lng":135.741928,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.8㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-539","desc":"本殿の東正面に南北棟で建つ。方一間、入母屋造銅板葺で周囲に切目縁を廻らす。四本柱に長押を廻らせ、柱上に舟肘木をおき格天井を張り、軒は小舞付の一軒疎垂木で、妻飾は木連格子である。本社拝殿同様に舞殿形式の拝殿で元禄再興期の境内の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012191"},{"id":"00012190","register_sub_id":"101","register_pk":"352990","name":"今宮神社若宮社本殿","kana":"いまみやじんじゃわかみやしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045486,"lng":135.741816,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-538","desc":"境内中ほどの西寄りに東面する三間社。春日造屋根を左右に並べ、棟をエ字形に繋ぐ独特な屋根形式をもつ。正側面に榑縁を廻らせて脇障子をたて、身舎正面各間に板唐戸をたてる。庇は総桁行を一間とし虹梁形の桁で軒を受ける。特異な形式と優美な意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012190"},{"id":"00012192","register_sub_id":"101","register_pk":"352992","name":"今宮神社若宮社門・透塀","kana":"いまみやじんじゃわかみやしゃもん・すきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04545175,"lng":135.74181863,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 透塀 木造、瓦葺、総延長26m","structure_material":"門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"26-540","desc":"本殿正面に開く門と、その両側から本殿を囲繞する透塀で切石積基礎に建つ。門は腕木門、切妻造で、猿頭付の段葺の屋根を目板瓦葺とする。透塀は柱に長押を廻らし、吹寄菱格子をいれ、腰を土壁、屋根は目板瓦葺とする。若宮の神域を画す丁寧なつくりの門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012192"},{"id":"00010002","register_sub_id":"101","register_pk":"196149","name":"宇良神社拝殿及び中殿","kana":"うらじんじゃはいでんおよびちゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府与謝郡伊根町字本庄浜191","lat":35.72889127,"lng":135.25783768,"geo_status":"db","era":"明治17／昭和中期改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0458","desc":"本殿正面に建ち、後方に中殿を張出す。広い柱間による桁行三間梁間二間の規模で、周囲を開放して高欄を廻らす。割拝殿形式をとり、側廻りを出組詰組とし、琵琶板の波紋や動植物、正面中央間の雲龍など要所を優秀な彫刻で飾る。明治期における中井権次の力作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010002"},{"id":"00010001","register_sub_id":"101","register_pk":"196148","name":"宇良神社本殿","kana":"うらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府与謝郡伊根町字本庄浜191","lat":35.72878867,"lng":135.25781989,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、茅葺、建築面積26㎡、井戸屋形付","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0457","desc":"境内奥に北面する建ちの高い茅葺本殿で、棟に千木と堅魚木を戴く。桁行三間梁間二間で周囲に縁を廻らし、正面中央に板唐戸を両折に吊る。主体部は直線的かつ簡素な意匠とし、縁の北東隅に取付く井戸屋形のみ彫刻を施す。丹後地方に分布する神明造系本殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010001"},{"id":"00009996","register_sub_id":"101","register_pk":"196143","name":"大本みろく殿","kana":"おおもとみろくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府綾部市本宮町本宮下1","lat":35.2960669,"lng":135.26127307,"geo_status":"db","era":"昭和28／昭和60改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄骨造及び木造平屋建一部地階付、銅板葺、建築面積1950㎡","structure_material":"鉄骨造及び木造平屋建一部地階付","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0452","desc":"桁行五〇メートルを超す大建築で、入母屋造妻入とし裳階を廻らす。西面に間口一〇メートルの入母屋玄関を構え、背面に張出す大神殿周りも入母屋屋根を重層させる。主構造は鉄骨造だが木材で化粧して木造に見せ、広大な広間に格天井を張る。壮大な規模の神殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009996"},{"id":"00016678","register_sub_id":"101","register_pk":"579162","name":"海眼寺観音堂","kana":"かいげんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府福知山市字寺38","lat":35.30491,"lng":135.122015,"geo_status":"db","era":"明治10年／昭和10年移築、令和6年改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0743","desc":"市街地北方の臨済宗寺院の観音堂。入母屋造妻入桟瓦葺で三方に縁を廻らし、正面向拝は虹梁形頭貫上に獅子と牡丹の彫刻を飾る。軸部は円柱、台輪上に外部三斗、内部出組を詰組に配す。内部格天井は中央の鏡天井に龍を描く。小規模ながら丁寧なつくりの仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016678"},{"id":"00016679","register_sub_id":"101","register_pk":"579163","name":"海眼寺山門","kana":"かいげんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府福知山市字寺38","lat":35.305193,"lng":135.12206,"geo_status":"db","era":"嘉永6年（1853）","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造2階建、瓦葺、建築面積6.0㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0744","desc":"通りに北面して建つ鐘楼門。切妻造桟瓦葺、一間一戸の楼門。下層は角柱、正面に虹梁形頭貫を架け、上層は円柱、台輪に大斗肘木を載せ、軒は一軒繁垂木。桁行三間の中央間に火灯窓を開け、高欄付縁を廻らす。木鼻や絵様など時代相を示し、境内の正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016679"},{"id":"00015477","register_sub_id":"101","register_pk":"533492","name":"興正寺阿弥陀堂","kana":"こうしょうじあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.99014167,"lng":135.75211111,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積399㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0692","desc":"御影堂の北隣に東面して建つ阿弥陀堂。二重、入母屋造本瓦葺で正面に三間向拝を付す。各層は禅宗様の尾垂木付き三手先斗栱で丸桁を受け、軒は下層を二軒繁垂木、上層を二軒扇垂木とする。全体に禅宗様を基調とし、御影堂とともに両堂形式で復興した近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015477"},{"id":"00015483","register_sub_id":"101","register_pk":"533498","name":"興正寺阿弥陀堂門","kana":"こうしょうじあみだどうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.99016389,"lng":135.75271389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、間口4.5m、袖塀付","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0698","desc":"阿弥陀堂の正面、堀川通りに東面して建つ四脚門。切妻造本瓦葺で両脇に袖塀を付す。総ケヤキ造で、柱上に三斗を組み、虹梁上の蟇股で棟木を支持し、軒は二軒繁垂木とする。本柱上部の正面側に施した龍など要所を精巧な彫刻で飾り、風格ある表構えをつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015483"},{"id":"00015479","register_sub_id":"101","register_pk":"533494","name":"興正寺経蔵","kana":"こうしょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.9903,"lng":135.75262222,"geo_status":"db","era":"嘉永元年（1848）","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡、輪蔵付","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0694","desc":"境内北東部に位置し、高欄付基壇上に南面して建つ経蔵。正面三間、側面四間、宝形造本瓦葺で正面に軒唐破風を飾り、唐破風造向拝を付す。下層外壁は漆喰塗で向拝まで塗込め、頂部に漆喰彫刻を廻らし内部土間中央に輪蔵を配す。楼造風の独特な意匠を持つ経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015479"},{"id":"00015476","register_sub_id":"101","register_pk":"533491","name":"興正寺御影堂","kana":"こうしょうじごえいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.98975,"lng":135.75211667,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1，123㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0691","desc":"七条堀川の北西に位置する浄土真宗興正寺派の本山寺院の御影堂。境内中央に東面して建つ入母屋造本瓦葺で正面に3間向拝を付す。内陣及び余間の柱や壁面は金箔押、組物及び欄間は極彩色とし、荘厳を極める。明治35年大火後に復興した、大規模な近代の仏殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015476"},{"id":"00015482","register_sub_id":"101","register_pk":"533497","name":"興正寺三門","kana":"こうしょうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98981111,"lng":135.75271389,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0697","desc":"御影堂の正面、堀川通りに東面して建つ入母屋造本瓦葺、三間三戸の楼門。柱は円柱で組物は三手先、隅は四手先、軒は二軒扇垂木。腰組を付し高欄付縁を廻らす。一階中央間の両脇羽目板を精緻な牡丹唐草彫刻で埋尽くし、本山寺院の正面を飾る軒反り雄大な三門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015482"},{"id":"00015480","register_sub_id":"101","register_pk":"533495","name":"興正寺鐘楼","kana":"こうしょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98951389,"lng":135.75267778,"geo_status":"db","era":"安永3年（1774）","year":1774,"year_source":"db","year_min":1774,"year_max":1774,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0695","desc":"境内南東部に位置する鐘楼。基壇上に北面して建つ桁行3間、梁間２間、入母屋造本瓦葺で腰組を廻らし四周に袴腰を付す。組物は三手先で隅のみ四手先、軒は二軒扇垂木で禅宗様、中備は蟇股や蓑束の和様とする折衷様式。明治大火を免れた境内最古の貴重な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015480"},{"id":"00015478","register_sub_id":"101","register_pk":"533493","name":"興正寺高廊下","kana":"こうしょうじたかろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.98997222,"lng":135.75213889,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0693","desc":"御影堂と阿弥陀堂の間を繋ぐ唐破風造本瓦葺の渡廊下。軸部は几帳面取の角柱を頭貫で固め、大斗肘木上に桁を通し、梁中央の笈形付き大瓶束で棟木を受ける。床には長尺の板を張り天井は輪垂木の化粧軒裏天井。細部意匠も優れた廊下で本山寺院の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015478"},{"id":"00015481","register_sub_id":"101","register_pk":"533496","name":"興正寺手水屋形","kana":"こうしょうじちょうずやがた","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98988611,"lng":135.75239722,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、瓦葺、面積7.8㎡、手水鉢付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0696","desc":"御影堂の北東に建つ手水屋形。入母屋造本瓦葺の東西棟で、四方転びの柱を頭貫で固め、台輪上に三斗を組み、軒は二軒繁垂木。中備は龍の彫刻付蟇股。内部は石敷床の中央に手水鉢を配し、上部は格天井を張る。小規模ながら良質なつくりで境内を構成する手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015481"},{"id":"00015484","register_sub_id":"101","register_pk":"533499","name":"興正寺東面北側築地塀","kana":"こうしょうじとうめんきたがわついじへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.99028333,"lng":135.75273333,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長24m","structure_material":"土塀","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0699","desc":"境内北方の東面を画し、阿弥陀堂門の両脇に延びる本瓦葺の塀。切石積基礎に一間毎に立てた柱を桁で繋ぎ、梁先で軒桁を支持する。軒は二軒繁垂木。外側は漆喰塗仕上とし、定規筋五本を付す。阿弥陀堂門に連なり、堀川通沿いに重厚な境内景観をつくる築地塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015484"},{"id":"00015485","register_sub_id":"101","register_pk":"533500","name":"興正寺東面南側築地塀","kana":"こうしょうじとうめんみなみがわついじへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98963056,"lng":135.75276389,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土塀、瓦葺、延長45m","structure_material":"土塀","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0700","desc":"三門の南袖塀から矩折れして南へ延びる本瓦葺の塀。切石積基礎上に一間毎に柱を立てて桁で繋ぎ、梁先で軒桁を支持する。軒は二軒疎垂木。外側は漆喰塗仕上とし、定規筋五本を付す。境内東面を画す一連の築地塀で、堀川通沿いに風格ある寺院の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015485"},{"id":"00010641","register_sub_id":"101","register_pk":"201215","name":"金戒光明寺大方丈","kana":"こんかいこうみょうじおおほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019655,"lng":135.788019,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積581㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0474","desc":"御影堂の東北方に南面して建ち、桁行一三間梁間一一間で、入母屋造桟瓦葺屋根を架ける。六室からなる方丈形式で、正面に広縁、両側と背面に畳縁、外周に切目縁を廻す。各部の比例が優れた上質かつ雄大な書院造で、蟻壁の横連子や天井等の細部も精緻である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010641"},{"id":"00010643","register_sub_id":"101","register_pk":"201217","name":"金戒光明寺唐門","kana":"こんかいこうみょうじからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019397,"lng":135.787997,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、銅板葺、面積7.3㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0476","desc":"大方丈の南正面、上面四半敷とした切石積基壇に建つ。四脚門形式で、丸柱と面取角柱を長押と頭貫で固め、屋根は向唐破風造の銅板葺、軒は二軒疎垂木で木舞打とする。扉と壁にある繊細な吹寄菱欄間、濃密な絵様繰形細部など、昭和初期の造形が凝縮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010643"},{"id":"00010642","register_sub_id":"101","register_pk":"201216","name":"金戒光明寺玄関","kana":"こんかいこうみょうじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019534,"lng":135.788212,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0475","desc":"大方丈東側にあり、寺務所と接続する。南北棟の入母屋造桟瓦葺の妻入で、正面中央に唐破風造銅板葺の車寄を設ける。六室からなる縦長の平面で、背面に幅広廊下を配する。板敷の応接室と書院造の座敷の対比、和風意匠に加味された洋風細部など、見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010642"},{"id":"00010644","register_sub_id":"101","register_pk":"201218","name":"金戒光明寺築地塀","kana":"こんかいこうみょうじついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019405,"lng":135.787959,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土塀、瓦葺、総延長57m","structure_material":"土塀","registered":"2015.08.04(平成27.08.04)","register_no":"26－0477","desc":"唐門から矩折れで延び、西側は大方丈南西隅に、東側は玄関の南西隅にそれぞれ至り、大方丈の南庭を区画する。切石積基壇に建ち、壁面に定規線五本を入れ、一間毎に太い柱を立てて腕木で桁を出し、本瓦葺屋根を受ける。格調高い境内空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010644"},{"id":"00010640","register_sub_id":"101","register_pk":"201214","name":"金戒光明寺御影堂","kana":"こんかいこうみょうじみえいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019555,"lng":135.787555,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積706㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0473","desc":"桁行七間梁間七間、正面に三間向拝を設け、雄大な入母屋造本瓦葺の屋根を架け、ほぼ南面して建つ。横長の外陣と縦長の内陣及び両脇陣からなる平面で、和様が基調の軸部に、尾垂木付二手先組物をあげ、洗練された細部をもち、本山格に相応しい堂姿を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010640"},{"id":"00010000","register_sub_id":"101","register_pk":"196147","name":"雙栗神社石鳥居","kana":"さぐりじんじゃいしとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.87562901,"lng":135.75464,"geo_status":"db","era":"元禄15","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"石造、高さ6.5m、幅5.5m","structure_material":"石造","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0456","desc":"境内西端に位置する。花崗岩を用いた石造明神鳥居で、柱間五・五メートル、高さ六・五メートルを測る大型の石鳥居である。近辺の中小社の遺構としては古例であり、規模においては最大級である。古社の入口を荘厳するのにふさわしい雄大さを持ち合わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010000"},{"id":"00009999","register_sub_id":"101","register_pk":"196146","name":"雙栗神社玉垣","kana":"さぐりじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.87624068,"lng":135.75748668,"geo_status":"db","era":"江戸後期／昭和36改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、総延長44m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0455","desc":"本殿門両側から、本殿左右に矩折れにのび、東方は南面三間東面八間、西方は南面三間西面八間を数える。南面と東西面の前方五間は角連子の透塀、後方六間は尖頭形の板を並べた透塀とし、二種の形式を併用させて変化をつける。本殿廻りの神域を画す玉垣。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009999"},{"id":"00009997","register_sub_id":"101","register_pk":"196144","name":"雙栗神社拝殿","kana":"さぐりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.8760703,"lng":135.75756561,"geo_status":"db","era":"天明5","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0453","desc":"桁行三間梁間二間で中央間を馬道とし、左右に広い板間を設ける。天井が高く、開放的な印象を与える。組物は舟肘木で、中央間の楣上部に蟇股をおき、軒は一軒疎垂木とする。割拝殿形式でありながら、板間の外回り三方を壁にしており、類例の少ない形式である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009997"},{"id":"00009998","register_sub_id":"101","register_pk":"196145","name":"雙栗神社本殿門","kana":"さぐりじんじゃほんでんもん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.87616544,"lng":135.75756837,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、間口2.4m","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0454","desc":"本殿と拝殿の中間に建つ。正面一間側面一間、切妻造妻入の一戸門で、左右に玉垣を廻らせる。柱は頂部粽付で、前列は几帳面取、後列は小面取とし、前面柱間に両開の格子戸を吊る。組物は出三斗で、虹梁や木鼻には極彩色を施し、多彩な装飾を華麗に施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009998"},{"id":"00011155","register_sub_id":"101","register_pk":"205262","name":"慈済院表門","kana":"じさいいんおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.015943,"lng":135.675516,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口2.8m、東方潜戸付","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0506","desc":"玄関廊式台のほぼ正面、天龍寺の総門から本山庫裏に至る参道に面して建つ。一間薬医門、切妻造本瓦葺で、本柱頂部を繋ぐ冠木を男梁と女梁で挟み、男梁上の板蟇股で棟木を受ける。軒は二軒疎垂木である。天龍寺最古級の表門であり塔頭の表構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011155"},{"id":"00011152","register_sub_id":"101","register_pk":"205259","name":"慈済院庫裏","kana":"じさいいんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.016232,"lng":135.67557,"geo_status":"db","era":"寛政11","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0503","desc":"本堂東側に玄関廊を介して建つ。切妻造妻入の正面は、舟肘木で受ける妻梁上の中央に蟇股と虹梁大瓶束を組み、両脇に海老虹梁を飾る定型的な構成を見せ、絵様なども時代性をよく示す。平面はほぼ正方形で、東半を占める土間は大黒柱を中心に豪壮な梁組を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011152"},{"id":"00011153","register_sub_id":"101","register_pk":"205260","name":"慈済院玄関廊","kana":"じさいいんげんかんろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.016208,"lng":135.675472,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0504","desc":"本堂と庫裏の間を繋ぐ両下造の建物。東半に玄関の間をおいて入母屋造の式台玄関を構え、西半の一〇畳では虹梁を三筋架けて板蟇股で化粧屋根を支持する特異な構成をもつ。玄関と廊下の機能を兼備する一方で本堂と庫裏を繋ぐ開放的な大廊下形式の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011153"},{"id":"00011154","register_sub_id":"101","register_pk":"205261","name":"慈済院書院","kana":"じさいいんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.016416,"lng":135.675423,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0505","desc":"本堂北側に建ち、庭に面する北西面に切目縁を廻らせる。内部は八畳二室からなる書院を原型に、南西面に廻らせた広縁を取り込んで広い座敷としており、北東に床を備える。面皮柱など数寄屋意匠を摂取し、天龍寺で近世に遡る唯一の書院遺構として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011154"},{"id":"00011151","register_sub_id":"101","register_pk":"205258","name":"慈済院本堂","kana":"じさいいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.01623,"lng":135.675322,"geo_status":"db","era":"文化13","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0502","desc":"天龍寺の旧三門の北に位置する塔頭の本堂。南面する六間取の方丈形式で、室中を含む前三室は境に竹の節を設け、三室通しの棹縁天井を張る。四面広縁や上間後室の西側に床と付書院を設ける形式などに、禅宗塔頭寺院本堂としての特色を示し、意匠も洗練される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011151"},{"id":"00006548","register_sub_id":"101","register_pk":"107531","name":"実相院客殿","kana":"じっそういんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区岩倉上蔵町312","lat":35.079117,"lng":135.781509,"geo_status":"db","era":"享保6","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積362㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0264","desc":"承秋門院御所の一部を移築，間取を変更したものと伝える。複雑な平面に入母屋造，桟瓦葺の屋根を架け，車寄の軒は唐破風につくる。造作は丁寧で，上段の間から続く滝の間と波の間は能舞台にも用い，床を拭板張とし，意匠及び造作に優れたつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006548"},{"id":"00006549","register_sub_id":"101","register_pk":"107532","name":"実相院門","kana":"じっそういんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市左京区岩倉上蔵町312","lat":35.07898055,"lng":135.7818851,"geo_status":"db","era":"享保6","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造、瓦葺、間口5.1m、左右袖塀付","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0265","desc":"客殿とともに承秋門院御所から移築したものと伝える。境内の表門として東面して建つ間口１７尺規模の四脚門である。蟇股上の斗と実肘木で棟木を受ける。二軒疎垂木，木舞下地の化粧小屋で軽快なつくり。屋根は本瓦葺である。両脇に本瓦葺の築地塀が取り付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006549"},{"id":"00011982","register_sub_id":"101","register_pk":"211117","name":"上善寺観音堂","kana":"じょうぜんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.038254,"lng":135.763365,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-528","desc":"境内南東隅に西面して建つ。正面三間、側面三間、宝形造本瓦葺で一間向拝を付ける。側廻りは格子や舞良戸をたて、飛貫を虹梁形とする。内部は一室だが、後寄りに立てる円柱に虹梁を渡して結界とし、奥に仏壇を設ける。六地蔵の一所としての由緒を伝える仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011982"},{"id":"00011983","register_sub_id":"101","register_pk":"211118","name":"上善寺山門","kana":"じょうぜんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.038113,"lng":135.763194,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積7.5㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-529","desc":"境内南端に南面して構える、間口三・六メートルの一間薬医門、切妻造本瓦葺である。太い五平の本柱に冠木を渡して梁を四筋架け、本柱位置は梁下に女梁を組み、梁上に蟇股を載せ、内寄りの梁には蓑束を立てて実肘木と拳鼻を付す。重厚で装飾も豊かな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011983"},{"id":"00011981","register_sub_id":"101","register_pk":"211116","name":"上善寺書院","kana":"じょうぜんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.0387,"lng":135.763102,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積170㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-527","desc":"本堂の北東方に渡り廊下を介して建つ、寄棟造、桟瓦葺。平面は六間取の方丈形式で周囲に廊下を廻らす。中列後室を広い内陣として格天井を張り、上手となる西列は後室に座敷飾を備える。各室に長押を廻らし、室境に筬欄間を入れるなど、端正な意匠の書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011981"},{"id":"00011980","register_sub_id":"101","register_pk":"211115","name":"上善寺本堂","kana":"じょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.038466,"lng":135.762971,"geo_status":"db","era":"文化9年(1812)","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-526","desc":"境内中央に南面し、桁行五間、梁間六間、入母屋造本瓦葺で三間向拝を付け、縁を廻らす。内部は内陣と脇陣、外陣による浄土宗本堂の標準平面をもつ。側廻りは角柱に舟肘木をのせ、内陣周囲は円柱に三斗を組む。須弥壇廻りの意匠充実し、内部架構も見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011980"},{"id":"00014187","register_sub_id":"101","register_pk":"508817","name":"青蓮院青龍殿（旧大日本武徳会京都支部武徳殿）","kana":"しょうれんいんせいりゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市山科区厨子奥花鳥町28他","lat":35.00225556,"lng":135.78741667,"geo_status":"db","era":"大正2年／平成26年移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積537㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"26-0646","desc":"武道施設を東山の山上へ移築、護摩堂の外陣としたもの。中央の道場板間の上は高く吹き抜いて高窓を設け、切妻屋根の正背面に千鳥破風を飾る。道場周囲の観覧席は裳階下で、正面入口上は軒唐破風とする。移築時の改造も最小限で、保存良好な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014187"},{"id":"00013749","register_sub_id":"101","register_pk":"505305","name":"神光院客殿","kana":"じんこういんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06032778,"lng":135.74362222,"geo_status":"db","era":"文政9年(1826)","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 629","desc":"本堂東方に南面して建ち渡廊下で繋ぐ。桟瓦葺で、南面中央に入母屋造の式台玄関が突出する。平面は三行三列の九室の周囲に縁を廻らせ、上手となる西列は最奥を上段として床と棚を備え、中列奥に院主の間、下手東列に仏間等を配する。上質なつくりの接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013749"},{"id":"00013751","register_sub_id":"101","register_pk":"505309","name":"神光院山門","kana":"じんこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.05998611,"lng":135.74366944,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 631","desc":"境内南辺中央に東西棟で建つ。一間薬医門、切妻造本瓦葺。五平の太い本柱頂部に女梁を組み、厚めの冠木を渡し、男梁上に撥形の束を立てて棟木を受ける。軒は一軒で木小舞打の疎垂木とし、破風拝みに梅鉢懸魚を飾る。意匠質実ながら風格を備えた古刹の正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013751"},{"id":"00013748","register_sub_id":"101","register_pk":"505303","name":"神光院中興堂","kana":"じんこういんちゅうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06055278,"lng":135.74324444,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 628","desc":"本堂北西側に南面して建つ。正面三間奥行四間、宝形造の主体部正面に入母屋造屋根を付け、さらに張出して唐破風の向拝を構える等複雑な外観を呈す。主体部は畳敷の外陣と両脇陣の後方を板間の内陣とする。円形垂木の軒や屋根構成に創意が認められる近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013748"},{"id":"00013747","register_sub_id":"101","register_pk":"505301","name":"神光院本堂","kana":"じんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06035556,"lng":135.74335278,"geo_status":"db","era":"文政12年(1829)","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 627","desc":"境内の中程に南面する。桁行三間梁間四間、入母屋造銅板葺で正面に向拝を付す。角柱を立て組物は平三斗。内部は前一間を外陣、後三間を内陣として桁行一杯の仏壇を作る。内外陣境に結界は設けず正面全面に半蔀を建てる。江戸後期の中規模本堂の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013747"},{"id":"00013750","register_sub_id":"101","register_pk":"505307","name":"神光院蓮月庵","kana":"じんこういんれんげつあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06001667,"lng":135.74345,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 630","desc":"本堂前方、山門脇に南北棟で建つ。大田垣蓮月の寓居。切妻造桟瓦葺で南に下屋を張出し東・北面の土間入口に庇を廻らせる。内部は北東隅を土間、西側の三畳に不動明王を祀る。南半は玄関や台所を配す。煤竹詰打の天井や円窓など、数寄屋意匠を加味した小庵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013750"},{"id":"00000448","register_sub_id":"101","register_pk":"101438","name":"大覚寺心経殿","kana":"だいかくじしんきょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区嵯峨大沢町4-1","lat":35.02864224,"lng":135.67860758,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積31㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"26 － 0012","desc":"奉納された般若心経の写経を納めるための建物。木造の八角円堂を鉄筋コンクリートで模したもので，軒や縁の意匠等に素材の特性がいかされている。設計は昭和初期を代表する住宅建築家藤井厚二。藤井の住宅以外の珍しい作品として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000448"},{"id":"00008504","register_sub_id":"101","register_pk":"134900","name":"大聖寺表門","kana":"だいしょうじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03067893,"lng":135.7591623,"geo_status":"db","era":"江戸後期／大正11年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、間口3.5m","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0356","desc":"境内の東南角に位置する。間口三・五メートルと大型の一間一戸薬医門、切妻造本瓦葺。男梁を三通りに架け、本柱に女梁を挿し、斗を介して男梁を受ける。中備は妻が蟇股、中央が大瓶束。一軒疎垂木。尼門跡筆頭格の寺格にふさわしい堂々とした構えになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008504"},{"id":"00008503","register_sub_id":"101","register_pk":"134899","name":"大聖寺玄関","kana":"だいしょうじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03102702,"lng":135.75905567,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0355","desc":"宮御殿東に位置する。桁行一五メートル梁間五・三メートル、入母屋造桟瓦葺。東面に唐破風造銅板葺の大きな車寄せを突出。南から応接室、玄関、内玄関、納戸を並べ、背面に廊下を通す。伝統的な和風建築ながら、自動車等の利便を配慮するなど近代性を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008503"},{"id":"00008501","register_sub_id":"101","register_pk":"134897","name":"大聖寺残月亭","kana":"だいしょうじざんげつてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.0310195,"lng":135.75853176,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0353","desc":"宮御殿の西、渡り廊下を介して続く。Ｌ字型の入母屋造で、東と南に妻を見せる。トコや棚を構える四畳半台目の茶室を中央に、その南にトコと付書院を並べる六畳間、東に位牌の間や水屋を配する。質の良い材料で、丁寧に施工された近代茶室の佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008501"},{"id":"00008505","register_sub_id":"101","register_pk":"134901","name":"大聖寺高塀","kana":"だいしょうじたかへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03081507,"lng":135.75908264,"geo_status":"db","era":"昭和17年頃","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造、瓦葺、延長36m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0357","desc":"表門から玄関への通路と境内前庭を区切る高塀。玄関東南隅から南へ三六メートル延び、南面築地塀に至り、途中に通用口を二ヶ所穿つ。礎石上、土台を置き、方柱をたて、腕木を出し、軒桁を支持し、塀瓦を葺く。壁は漆喰仕上げ。簡素ながら厳粛な雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008505"},{"id":"00008506","register_sub_id":"101","register_pk":"134902","name":"大聖寺東面築地","kana":"だいしょうじとうめんついじ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03097939,"lng":135.75923867,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土塀、瓦葺、延長59m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0358","desc":"境内東辺、烏丸通沿いに位置する築地塀で、表門から北側に折れ曲がり五九メートル延びる。北寄りに通用門を設ける。本瓦を葺き、通り側に白線五線を入れる。通用門は正・背面に瓦庇を架け、引違い戸と片開戸の潜りを設ける。賑やかな烏丸通に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008506"},{"id":"00008507","register_sub_id":"101","register_pk":"134903","name":"大聖寺南面築地","kana":"だいしょうじなんめんついじ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03063042,"lng":135.75891529,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長66m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0359","desc":"境内南辺、小路沿いに設けられた築地塀。表門から西側隣地境まで延び、総延長六六メートルを測る。本瓦葺とし、小路側には白線五線を入れる。西寄りに間口一・八メートルの門口を穿ち、両開戸をたて、不浄の門とする。重厚な構えで、近世尼門跡の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008507"},{"id":"00008499","register_sub_id":"101","register_pk":"134895","name":"大聖寺本堂","kana":"だいしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03078888,"lng":135.75900805,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0351","desc":"境内東南寄りに西面して建つ。入母屋造桟瓦葺。六間取方丈形式、正面に広縁、正・側面に高欄付切目縁を巡らす。方柱で舟肘木とし、一軒疎垂木、妻木連格子。後列南室を貴人の間とし、花鳥を描く大トコを構える。伝統的な形式のなか、品格のある設えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008499"},{"id":"00008500","register_sub_id":"101","register_pk":"134896","name":"大聖寺宮御殿","kana":"だいしょうじみやごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03094931,"lng":135.75873481,"geo_status":"db","era":"江戸後期／文政8年（1825）頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0352","desc":"境内中央に南面して建つ。入母屋造の西棟と東に続く切妻造の東棟からなる。東棟は前後列各四室からなり、数寄屋風意匠になる。西棟はトコや違棚を構える主室ほか四室を田の字型に配し、周囲に畳縁を設ける。近世における尼門跡寺院の御殿の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008500"},{"id":"00008502","register_sub_id":"101","register_pk":"134898","name":"大聖寺渡り廊下","kana":"だいしょうじわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03090419,"lng":135.75900554,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0354","desc":"本堂と玄関を繋ぐ。桁行一二メートル梁間三・八メートル、両下造桟瓦葺。複廊になり、東側は内向きの通路で板張、西側は畳敷、両端部近くに襖や杉戸をたてて間仕切る。天井はいずれも棹縁天井。中間に防火壁を設けるなど近代的な要素も見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008502"},{"id":"00007068","register_sub_id":"101","register_pk":"108050","name":"建勲神社大鳥居","kana":"たけいさおじんじゃおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03850662,"lng":135.74462352,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、高さ7.2m、幅5.5m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0290","desc":"船岡山山麓、船岡東通に東面して建つ。木造の明神鳥居で、幅５．５ｍ高さ７．２ｍに及ぶ。礎石上に円柱を建て、貫と嶋木、笠木で固める。材は台湾阿里山産の檜で、素木のままとする。大規模で、笠木も大きく反り、神域の荘厳な結界を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007068"},{"id":"00007066","register_sub_id":"101","register_pk":"108048","name":"建勲神社貴賓館","kana":"たけいさおじんじゃきひんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.038555,"lng":135.744156,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0288","desc":"拝殿の東方に位置する。南北棟の入母屋造桟瓦葺で、緩やかな起りになる切妻造桟瓦葺の車寄を西面して付ける。桁行３間半梁間４間半で、南・東・西３方に跳高欄付切目縁をまわす。洛北から東山を望む、瀟洒な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007066"},{"id":"00007064","register_sub_id":"101","register_pk":"108046","name":"建勲神社祭器庫","kana":"たけいさおじんじゃさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.0387239,"lng":135.743774,"geo_status":"db","era":"明治13／昭和4移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0286","desc":"拝殿の東北方に位置する。南面する土蔵造２階建で、入母屋造本瓦葺の置屋根とする。地盤高の関係で２階に出入口を設け、１間庇を付ける。外壁は漆喰仕上げ。庇は桟瓦葺で、柱型を表し、塗り込める。側・背面に庇付窓を設け、外観を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007064"},{"id":"00007067","register_sub_id":"101","register_pk":"108049","name":"建勲神社社務所","kana":"たけいさおじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.038662,"lng":135.744003,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0289","desc":"貴賓館の西北に南面して建ち、廊下などを介して繋がる。入母屋造桟瓦葺で、玄関正面にこけら葺庇を付ける。中央東寄りの玄関土間を挟んで、東に旧宿直室、西に事務室、その西に旧宮司室を設ける。内法が高く、その上に小振りな屋根が載り、軽快な外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007067"},{"id":"00007063","register_sub_id":"101","register_pk":"108045","name":"建勲神社神饌所","kana":"たけいさおじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03855338,"lng":135.7432219,"geo_status":"db","era":"明治17／明治43移築","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0285","desc":"本殿透塀の南方に、東西棟で本殿に正面を向ける。桁行５間梁間３間規模の入母屋造檜皮葺。内部は桁行に３室に分け、東に土間と台所、中央に板間、西に８畳間を配する。天井はいずれも棹縁天井。入口土間に両開妻戸、縁に面して舞良戸をたてる。神饌所の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007063"},{"id":"00007062","register_sub_id":"101","register_pk":"108044","name":"建勲神社透塀","kana":"たけいさおじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03869716,"lng":135.74312943,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、延長55m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0284","desc":"本殿四周を囲む塀で、正面で祝詞舎両脇に付く。切石布基礎上に土台を載せ、方柱をたて、腰長押や内法長押で固め、腕木で桁を支持する。軒は疎垂木で、屋根桟瓦葺。柱間は腰板壁で菱格子、小壁にたすきを入れる。本殿まわりの空間を画し、森厳な雰囲気をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007062"},{"id":"00007065","register_sub_id":"101","register_pk":"108047","name":"建勲神社手水舎","kana":"たけいさおじんじゃちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03854628,"lng":135.74369966,"geo_status":"db","era":"明治13／大正11移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造、檜皮葺、面積4.2㎡","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0287","desc":"拝殿の東南方に所在する。桁行１間梁間１間、東西棟の切妻造檜皮葺で、緩い勾配とする。礎石上に方柱をたて、内法貫で固め、舟肘木を介し、虹梁や桁を支持。豕叉首を組み、軒は一軒疎垂木。周囲に菱格子欄間を置く。化粧屋根裏天井で、中央に石製水盤を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007065"},{"id":"00007060","register_sub_id":"101","register_pk":"108042","name":"建勲神社祝詞舎","kana":"たけいさおじんじゃのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03865396,"lng":135.74337735,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積7.1㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0282","desc":"本殿の前方に位置する。桁行１間梁間１間で、前寄り柱筋に両開戸をたてる。切妻造妻入檜皮葺。円柱で、柱上に舟肘木を置き、内法貫や虹梁、桁で固める。梁行中備に蟇股を置き、妻は豕叉首。緩い起り屋根に、一軒疎垂木とし、穏やかな表情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007060"},{"id":"00007059","register_sub_id":"101","register_pk":"108041","name":"建勲神社拝殿","kana":"たけいさおじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03863734,"lng":135.74346929,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0281","desc":"本殿の東方に位置する吹放ちの拝殿。桁行２間梁間３間で、四周に切目縁をまわす。入母屋造妻入檜皮葺で、妻を木連格子とする。面取方柱で、柱上に舟肘木を置き、軒は二軒疎垂木。拭板敷で、折上小組格天井を張る。軒反の大きい優美な外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007059"},{"id":"00007058","register_sub_id":"101","register_pk":"108040","name":"建勲神社本殿","kana":"たけいさおじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03868652,"lng":135.7431831,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.1㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0280","desc":"船岡山山頂に東面して建つ１間社流造の本殿。四周に組高欄付縁をまわし、正面に木階、浜床、浜縁を付ける。身舎は円柱、向拝は面取方柱。組物は舟肘木で、妻は豕叉首。二軒繁垂木とし、打越垂木を疎垂木とする。簡明な意匠になる近代本殿の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007058"},{"id":"00007061","register_sub_id":"101","register_pk":"108043","name":"建勲神社渡廊","kana":"たけいさおじんじゃわたろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03867,"lng":135.74328521,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0283","desc":"本殿と祝詞舎を繋ぐ。桁行２間梁間１間で、切妻造妻入銅板葺。方柱上に舟肘木を載せ、梁及び桁を架し、梁中央に撥束を立て、舟肘木を介して棟木を支持する。床は中央通りを石敷とし、天井は一軒疎垂木の化粧屋根裏とする。簡易な構造で、軽快な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007061"},{"id":"00012216","register_sub_id":"101","register_pk":"353016","name":"玉田神社一の鳥居","kana":"たまたじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町中島向野12-2","lat":34.894776,"lng":135.736631,"geo_status":"db","era":"文化年間（1804-1817）","year":1810,"year_source":"estimated","year_min":1804,"year_max":1817,"year_label":"文化年間（1804-1817）","structure":"石造、間口3.7m、高さ4.3m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"26-564","desc":"境内の北西方に建つ石造明神鳥居。間口三・七メートル、高さ四・三メートル。内転びの柱に貫を通し、その中央には額束を立て、柱上に一体で造られた島木と笠木を載せる。笠木は端部において反りをもつ。地域の歴史的景観を良好に形成する鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012216"},{"id":"00012217","register_sub_id":"101","register_pk":"353017","name":"玉田神社二の鳥居","kana":"たまたじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町森宮西地内","lat":34.892336,"lng":135.737257,"geo_status":"db","era":"享保年間（1716-1735）／文化年間（1804-1817）移築","year":1726,"year_source":"estimated","year_min":1716,"year_max":1735,"year_label":"享保年間（1716-1735）","structure":"石造、間口3.4m、高さ4.1m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"26-565","desc":"境内の南面を東西に走る祭礼道の入口に建つ石造明神鳥居。間口三・四メートル、高さ四・一メートルで、一の鳥居と同形式であるが、規模が小さく柱径が太いため、安定感のある造形をみせており、時代の古さが感じられる。地域の歴史を今に伝える鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012217"},{"id":"00012214","register_sub_id":"101","register_pk":"353014","name":"玉田神社本殿","kana":"たまたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町森宮東1","lat":34.8932,"lng":135.739256,"geo_status":"db","era":"寛永元年(1624)／文化2年(1805)改修","year":1624,"year_source":"db","year_min":1624,"year_max":1624,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-562","desc":"田園地帯の台地に境内を構える。本殿は南面し、寛永元年の八間社を文化二年に縮小し四間社流造、向拝一間とした。柱や桁など軸部に寛永材が残り、実肘木に江戸初期の特徴を示す。蟇股や手挟、脇障子の彫刻は文化材で花鳥、唐獅子など華やかな細部意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012214"},{"id":"00012215","register_sub_id":"101","register_pk":"353015","name":"玉田神社末社市杵社","kana":"たまたじんじゃまっしゃいちきしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町森宮東1","lat":34.893102,"lng":135.739367,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-563","desc":"本殿の南東の覆屋内に西面して建つ。一間社流造、こけら葺で、正側面に縁を廻らして脇障子をたて、正面に木階五級、浜床、浜縁を設ける。組物は三斗、中備は蟇股で側面板壁と共に彩色の痕跡をよく残る。妻飾は虹梁豕叉首組で、小社ながら整った意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012215"},{"id":"00008143","register_sub_id":"101","register_pk":"132584","name":"自玉手祭来酒解神社本殿","kana":"たまてよりまつりきたるさかとけじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字天王山3-1","lat":34.90168074,"lng":135.67869656,"geo_status":"db","era":"文政3年（1820）","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0344","desc":"天王山山頂東側の平坦部に鎮座する大型社殿。五間社流造、檜皮葺で、銅板仮葺とする。身舎は四周に縁をめぐらし、脇障子を建てる。庇部分は身舎より一段低く、三方に菱格子戸をたてて前室とする。欄間や蟇股の彫刻は、枠面から横溢させて雄壮に彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008143"},{"id":"00014049","register_sub_id":"101","register_pk":"508309","name":"知恩院阿弥陀堂","kana":"ちおいんあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区新橋通大和大路東入三丁目林下町442","lat":35.005175,"lng":135.78263333,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0641","desc":"中心伽藍の南西、御影堂の西に東面して建つ仏堂。入母屋造本瓦葺で裳階に向拝三間がつく。内陣の南北が脇間で東を外陣とする。須弥壇はやや低く像高のある阿弥陀如来坐像を納める。設計木子清敬、棟梁市田重郎兵衛。近世の伝統を引く近代仏堂の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014049"},{"id":"00014050","register_sub_id":"101","register_pk":"508310","name":"知恩院阿弥陀堂渡廊下","kana":"ちおいんあみだどうわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区新橋通大和大路東入三丁目林下町442","lat":35.00533333,"lng":135.78279722,"geo_status":"db","era":"明治43年／昭和40年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0642","desc":"国宝御影堂の西縁から西へ延び、南へ折れて阿弥陀堂北縁に取付く。本瓦葺の屋根は照り起りで両端を唐破風に造る。柱間は吹放ち、御影堂縁に合わせて高く床を張り、東から四間目は境内通路のため更に床を切り上げる。壮大な堂宇の間を繋ぐ荘重な渡廊下である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014050"},{"id":"00014051","register_sub_id":"101","register_pk":"508311","name":"知恩院納骨堂","kana":"ちおいんのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区新橋通大和大路東入三丁目林下町442","lat":35.00455,"lng":135.78404167,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0643","desc":"御影堂南東の高台に建つ方一間の裳階付である。屋根は宝形造の本瓦葺とする。壇上積基壇に建ち、四手先で軽快な軒を受ける。内部は四半瓦敷で、螺鈿細工の須弥壇を据え、内部彩色は紙上に施す。設計は阪谷良之進。古典理解に基づく造形は近代仏堂の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014051"},{"id":"00014863","register_sub_id":"101","register_pk":"519123","name":"東福寺恩賜門","kana":"とうふくじおんしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.976825,"lng":135.77408056,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、檜皮葺、間口3.9m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0663","desc":"昭憲皇太后恩賜による一間一戸檜皮葺の唐門。設計は亀岡末吉。礎盤に円柱を立て貫で固めて三斗を組み、軒は一軒繁垂木。中備は蟇股とし、虹梁上に大瓶束を置き、大斗肘木で棟木を支持。菊紋付扉を吊り、欄間、蟇股、虹梁上など繊細な透彫で飾る華麗な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014863"},{"id":"00014864","register_sub_id":"101","register_pk":"519124","name":"東福寺唐門","kana":"とうふくじからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97699444,"lng":135.77379167,"geo_status":"db","era":"明治23年／明治42年頃増築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造、瓦葺、間口4.2m、歩廊付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0664","desc":"方丈の西に開く一間一戸本瓦葺の唐門。方丈との間に落棟で唐破風屋根の歩廊が取付く。門は礎石上に円柱を立て三斗を組み、中備は蟇股を模した龍の彫刻で飾り、梁上に笈形付大瓶束を配す。門口に桟唐戸を開く。全体に装飾少なく簡素ながら整った意匠の唐門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014864"},{"id":"00014862","register_sub_id":"101","register_pk":"519122","name":"東福寺庫裏","kana":"とうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97672778,"lng":135.77441389,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積559㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0662","desc":"方丈南東に位置する切妻造桟瓦葺。西に唐破風造銅板葺の式台玄関、南に起り付き切妻造桟瓦葺の脇玄関を付す。内部は方形の平面中央に、式台玄関、脇玄関及び北東の座敷に至る板敷床の中廊下を通す。大規模な切妻造屋根の庫裏が伽藍中枢の雄大な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014862"},{"id":"00014869","register_sub_id":"101","register_pk":"519129","name":"東福寺通霄門","kana":"とうふくじつうしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97665,"lng":135.77364167,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造及び木造、瓦葺、間口4.6m","structure_material":"鉄筋コンクリート造及び木造","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0669","desc":"通天橋と本堂の間の南寄りに開く切妻造本瓦葺の門。四隅の角柱と頭貫を鉄筋コンクリート造とし、頭貫から上部を木造とする混構造。組物は三斗を組み、虹梁上の大瓶束に蟇股風の笈形を付す。軒は一軒繁垂木。南歩廊と一体となり、雄大な伽藍景観をつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014869"},{"id":"00014866","register_sub_id":"101","register_pk":"519126","name":"東福寺通天橋","kana":"とうふくじつうてんきょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97729167,"lng":135.77366944,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造及び木造平屋建、瓦葺、建築面積99㎡","structure_material":"鉄筋コンクリート造及び木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0666","desc":"稲荷山から流れる三ノ川に架かる橋。鉄筋コンクリート造橋脚を懸造状に構築し、上部を木造切妻造本瓦葺の歩廊とする。西面中央を突出させて、西方の景色を望む視点場とし、飛貫上には優美な蟇股を飾る。木柄の細い列柱が、谷を渡る歩廊の軽快さを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014866"},{"id":"00014867","register_sub_id":"101","register_pk":"519127","name":"東福寺通天橋北歩廊","kana":"とうふくじつうてんきょうきたほろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97763333,"lng":135.77369722,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0667","desc":"通天橋とその北東高台にある塔頭常楽庵を結ぶ登廊。梁間一間切妻造本瓦葺及び桟瓦葺で、北東に向かって２箇所で折曲がり、地形に沿って屋根に傾斜をつける。柱頂部に直接梁を架けた簡明な構造で、傾斜を軽快に登る列柱が、境内に立体感ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014867"},{"id":"00014868","register_sub_id":"101","register_pk":"519128","name":"東福寺通天橋南歩廊","kana":"とうふくじつうてんきょうみなみほろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97689167,"lng":135.77365833,"geo_status":"db","era":"明治44年／昭和38年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0668","desc":"通天橋と本堂を結び、直線状に延びる歩廊。梁間一間の切妻造本瓦葺で、通霄門を挟んで本堂基壇に接続し、西面北寄りで唐門まで突出する。腰貫を通した円柱上に直接梁を架け、束で棟木を支えた簡明な構造。長大な歩廊の列柱が、壮大な伽藍の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014868"},{"id":"00014861","register_sub_id":"101","register_pk":"519121","name":"東福寺通天台","kana":"とうふくじつうてんだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97721389,"lng":135.77395,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0661","desc":"方丈の北西に位置し、通天橋を眺める展望台。桁行３間梁間１間、平屋建切妻造桟瓦葺。土台に立てた円柱の頂部に直接梁を架け、貫で軸部を固める。床は板敷とし、上部は化粧屋根裏、柱間は吹放ち、腰に高欄を嵌める。小規模ながら方丈北西の姿を印象付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014861"},{"id":"00014860","register_sub_id":"101","register_pk":"519120","name":"東福寺方丈","kana":"とうふくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97704167,"lng":135.77410833,"geo_status":"db","era":"明治23年／明治43年頃増築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積624㎡、廊下付","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0660","desc":"本堂の北に位置する桁行16間梁間９間入母屋造本瓦葺。六間取りで南と東に吹放ちの広縁、西に入側縁を付し、四周に高欄付濡縁を廻らし、南西に廊下附属。室中は桁行7間梁間4間半と広大で、北西は床を備えた御所の間。規模雄大で上質な明治期屈指の方丈。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014860"},{"id":"00014865","register_sub_id":"101","register_pk":"519125","name":"東福寺方丈築地塀","kana":"とうふくじほうじょうついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97683611,"lng":135.77385556,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土塀、瓦葺、総延長78m","structure_material":"土塀","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0665","desc":"方丈の西と南を囲い、西面の唐門と南面の恩賜門に取り付く、折れ曲がり総延長78メートルの築地塀。切石積基礎に柱を一間毎に立て、本瓦葺とする。外壁は鼠色漆喰塗で五条の定規筋を白漆喰塗、内壁は白漆喰塗とする。方丈の外周を廻り、伽藍景観を整える塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014865"},{"id":"00014859","register_sub_id":"101","register_pk":"519119","name":"東福寺本堂","kana":"とうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97633889,"lng":135.77380556,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積809㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0659","desc":"東山に位置する臨済宗東福寺派大本山寺院の本堂。壇上積基壇に建つ桁行五間梁間三間、一重入母屋造本瓦葺裳階付。組物は本屋三手先、裳階出組、軒はいずれも二軒扇垂木。内部四半敷土間は天井高く張り、北寄り中央に須弥壇を配す。規模壮大な近代屈指の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014859"},{"id":"00001397","register_sub_id":"101","register_pk":"102387","name":"日本聖公会京都聖三一教会","kana":"にほんせいこうかいきょうとせいさんいちきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区聚楽廻中町45-1","lat":35.017673,"lng":135.740875,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0049","desc":"階下を幼稚園，階上を礼拝堂に充てる。基礎を煉瓦，階下を縦板貼りとした和風真壁造的なハーフティンバースタイルの教会建築で，礼拝堂は幾何学的曲線を用いた軽快なトラス小屋組を持つ。設計はバーガミニー。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001397"},{"id":"00009039","register_sub_id":"101","register_pk":"162399","name":"仁和寺大玄関","kana":"にんなじおおげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02852919,"lng":135.71317256,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積127㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0381","desc":"御殿群南端に東面して建つ。桁行12メートル梁間7.0メートル、入母屋造桟瓦葺で、東正面に間口6.0メートル近い大きな唐破風造檜皮葺の車寄を構える。細部では蟇股や大瓶束の笈形に秀麗な彫刻を施すなど、威厳と華やかさを備えた大型の玄関である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009039"},{"id":"00009041","register_sub_id":"101","register_pk":"162401","name":"仁和寺黒書院","kana":"にんなじくろしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.0290146,"lng":135.7128909,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0383","desc":"宸殿西側に南面して並び建ち、桁行15.5メートル梁間11.7メートル、入母屋造桟瓦葺で、宸殿と白書院の双方と、檜皮葺屋根の渡廊下で繋ぐ。平面は方丈型六間取で、西奥室に座敷飾を備える。周囲に舞良戸を建て、内向きの書院らしく落着いた外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009041"},{"id":"00009044","register_sub_id":"101","register_pk":"162404","name":"仁和寺皇族門","kana":"にんなじこうぞくもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.0285981,"lng":135.71337332,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、檜皮葺、間口2.7m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0386","desc":"大玄関から東にのびる塀の中間に構える門で、四脚平唐門、檜皮葺である。本柱は円柱、控え柱は角柱で、男梁上の蟇股と舟肘木で棟木を受け、軒は大疎垂木とし、桟唐戸の上に透彫欄間を入れる。御殿群の前庭と内庭を仕切る、木割の細い、繊細な姿の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009044"},{"id":"00009040","register_sub_id":"101","register_pk":"162400","name":"仁和寺白書院","kana":"にんなじしろしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02878388,"lng":135.71306769,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0382","desc":"宸殿と大玄関の間に東面して建ち、桁行一15.8メートル梁間12.5メートル、入母屋造桟瓦葺である。表と裏に三室ずつ配る六室構成で、正面広縁を吹放しとする。表側の室境は竹の節欄間とし座敷にトコと棚を設える。旧宸殿としての格調を備える書院である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009040"},{"id":"00009038","register_sub_id":"101","register_pk":"162398","name":"仁和寺宸殿","kana":"にんなじしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02898164,"lng":135.71317855,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積257㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0380","desc":"境内南西の御殿群中央に建つ。桁行19.7メートル梁間11.8メートル、入母屋造檜皮葺である。寝殿造の外観、書院造の内部構成を組み合わせ、東側に中門廊風の突出を設ける。内外とも門跡寺院に相応しい優雅な意匠で、亀岡末吉の代表作のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009038"},{"id":"00009043","register_sub_id":"101","register_pk":"162403","name":"仁和寺勅使門","kana":"にんなじちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02871496,"lng":135.71354112,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、檜皮葺、間口5.2m、左右袖塀付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0385","desc":"白書院正面に東面して建ち、四脚門、前後唐破風造側面入母屋、檜皮葺である。本願寺唐門を模した形式をもち、壁面や桟唐戸などを、花菱や鳳凰、唐草などを図案化した流麗な透彫りで埋め尽くす。亀岡末吉の意匠感覚が発揮された見応えのある大型の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009043"},{"id":"00009045","register_sub_id":"101","register_pk":"162405","name":"仁和寺霊宝館","kana":"にんなじれいほうかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.0292693,"lng":135.71435914,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積376㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0387","desc":"境内のほぼ中央に建ち、鉄筋コンクリート造二階建、建築面積376平方メートル、桟瓦葺である。平面はロの字形で、南面中央に切妻造のポーチを突出させる。外壁は校倉造を模した構成で、垂木や虹梁も現すなど、コンクリートによる和風表現の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009045"},{"id":"00009042","register_sub_id":"101","register_pk":"162402","name":"仁和寺霊明殿","kana":"にんなじれいめいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02928728,"lng":135.71301375,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積53㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0384","desc":"黒書院の北側に渡り廊下を介して南面して建ち、方三間、宝形造、一間向拝付、檜皮葺である。内部は一室で三間幅の仏壇を設け、折上小組格天井を張る。平安後期頃の様式を意識した構成としつつ、蟇股には亀岡末吉の得意とした唐草を図案化した彫刻を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009042"},{"id":"00015320","register_sub_id":"101","register_pk":"532444","name":"乃木神社記念館","kana":"のぎじんじゃきねんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93298611,"lng":135.77643333,"geo_status":"db","era":"大正5年頃／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造平屋建、茅葺（鉄板仮葺）、建築面積82㎡","structure_material":"石造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0681","desc":"境内北東に位置し、乃木希典が満州で司令部に用いた家屋を再現したと伝わる記念館。西面して建つ石造切妻造平入茅葺（鉄板仮葺）で、戸口や窓廻りを煉瓦積、正面外壁を漆喰塗仕上。中央に玄関ホール、北と南に部屋を配す。境内に独特な存在感を示す記念館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015320"},{"id":"00015322","register_sub_id":"101","register_pk":"532446","name":"乃木神社神門及び袖塀","kana":"のぎじんじゃしんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93308333,"lng":135.77592222,"geo_status":"db","era":"大正5年／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"神門 木造、銅板葺、間口5.5m 袖塀 木造、瓦葺、総延長27m","structure_material":"神門 木造","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0683","desc":"境内北西の入口に建つ四脚門と両脇の塀。設計は設樂貞雄。神門は入母屋造平入銅板葺。組物は実肘木付平三斗、軒は二軒繁垂木とし、門口に板扉を開く。塀は本瓦葺で外壁漆喰塗とし、腰は簓子下見板張。軒反り強く雄大な門で、塀とともに境内の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015322"},{"id":"00015319","register_sub_id":"101","register_pk":"532443","name":"乃木神社拝殿","kana":"のぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93248889,"lng":135.776425,"geo_status":"db","era":"大正5年／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0680","desc":"本殿の北に位置する拝殿。設計は設樂貞雄。桁行3間梁間2間入母屋造平入銅板葺。組物は舟肘木、軒は二軒疎垂木。内部は一室の板敷で格天井を張る。正背面中央間の板扉以外は蔀戸で四周に刎高欄付縁を廻らす開放的なつくり。本殿とともに境内景観の要をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015319"},{"id":"00015321","register_sub_id":"101","register_pk":"532445","name":"乃木神社宝物館","kana":"のぎじんじゃほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93316944,"lng":135.77638889,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0682","desc":"境内北東に位置する乃木夫妻の遺品展示施設。基壇上に西面して建つ、土蔵造２階建切妻造平入本瓦葺。外壁は漆喰塗仕上で、一階は海鼠壁仕上。二階には乃木夫妻の祠を配し、二重虹梁上に撥束を立てるなど特徴的な小屋組。外観重厚で境内景観を構成する宝物館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015321"},{"id":"00015318","register_sub_id":"101","register_pk":"532442","name":"乃木神社本殿","kana":"のぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93225556,"lng":135.77648889,"geo_status":"db","era":"大正5年／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0679","desc":"桃山御陵の南に位置し、乃木希典と妻を祀る神社の本殿。設計は設樂貞雄。境内南辺に北面して建つ桁行三間梁間三間、入母屋造妻入銅板葺で一間向拝付き。三方に縁を廻らし、脇障子を建てる。向拝中備は蟇股上に二つの斗を配す。基壇上に建つ堂々たる姿の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015318"},{"id":"00002929","register_sub_id":"101","register_pk":"103919","name":"平安神宮内廻廊","kana":"へいあんじんぐううちかいろう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.01665983,"lng":135.78271494,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0119","desc":"昭和１５年の一連の造営時に建てられた。西側と東側に分かれ，内拝殿と北東及び北西歩廊をつなぎ，大極殿背後の空間を区画している。基壇上にあって，１間幅の外側を連子窓を設けた壁とし，内側は円柱を建て，屋根は緩やかな反りをもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002929"},{"id":"00002939","register_sub_id":"101","register_pk":"103929","name":"平安神宮大鳥居","kana":"へいあんじんぐうおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町・岡崎円勝寺町","lat":35.01255205,"lng":135.78268762,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造、高さ24m、幅18m","structure_material":"鉄筋コンクリート造一部鉄骨造","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0129","desc":"昭和天皇大礼を記念して建てられた。設計は京都府技師の阪谷良之進。構造は鉄筋コンクリート及び鉄骨造、形式は明神鳥居で、幅18ｍ、高24ｍになり、当時国内最大であった。柱が太いプロポーションが特徴で、洛東岡崎のシンボルとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002939"},{"id":"00002932","register_sub_id":"101","register_pk":"103922","name":"平安神宮額殿","kana":"へいあんじんぐうがくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01581375,"lng":135.78189755,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0122","desc":"南内庭西側に位置する。規模，構造形式は神楽殿と同一とするが，内部は四半敷の総土間とする。東，南，北の３面は中央に板唐戸，両脇に蔀戸を立て，西面で廻廊に接続する。参拝者の休憩や講演などを目的とした建物で，境内景観上欠くことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002932"},{"id":"00002931","register_sub_id":"101","register_pk":"103921","name":"平安神宮神楽殿","kana":"へいあんじんぐうかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01582604,"lng":135.78300004,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0121","desc":"南内庭東側に位置し，東外廻廊と東側で接続する。基壇を設けて桁行８間，梁間４間の丸柱を建て，南，西，北の３面１間通りを吹き放しとする。屋根は入母屋造，本瓦葺。神楽の奉奏とともに結婚式等を行う場として建てられたもので，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002931"},{"id":"00002936","register_sub_id":"101","register_pk":"103926","name":"平安神宮斎館","kana":"へいあんじんぐうさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.015709,"lng":135.783279,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積448㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0126","desc":"東外廻廊の外側に位置する。木造平屋建，瓦葺一部銅板葺，建築面積４４８㎡。廻廊内の丹塗の建物群とは趣を異にするが，床・棚を備え折上小組格天井とする旧供進使室など内外ともに質が高く，唐破風造の玄関を備えるなど，近代和風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002936"},{"id":"00002935","register_sub_id":"101","register_pk":"103925","name":"平安神宮神門翼廊","kana":"へいあんじんぐうしんもんよくろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01542679,"lng":135.78277227,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積300㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0125","desc":"神門（応天門）両脇から東西に延び，それぞれ梁間２間，桁行４間の南北棟につながる。神門脇には扉口を開き，１間おいて両外側は畳敷きの室内とする。木部は破風板等も含めて丹塗とし，屋根は本瓦葺。境内の正面側景観を形つくる要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002935"},{"id":"00002926","register_sub_id":"101","register_pk":"103916","name":"平安神宮透塀及び後門","kana":"へいあんじんぐうすきべいおよびこうもん","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.017067,"lng":135.78244,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造透塀、銅板葺、折曲り延長90m、及び棟門、間口3.0m","structure_material":"木造透塀","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0116","desc":"昭和１５年，孝明天皇合祀時に行われた一連の造営の一つ。これらの設計は内務省神社局技師であった角南隆と谷重雄である。一間棟門の後門を中心に左右に透塀を延ばし，当初は総延長で１１４ｍに達していた。本殿の背後を区切る建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002926"},{"id":"00002938","register_sub_id":"101","register_pk":"103928","name":"平安神宮西祭器庫","kana":"へいあんじんぐうにしさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01569852,"lng":135.78132441,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0128","desc":"東祭器庫の西側に並ぶ。東祭器庫に倣って造られたもので，ほぼ同様の規模，形式，意匠を持つが，外壁腰部など細部意匠が異なる。内部は二階建とし，小屋はトラス組になる。軒部は漆喰で塗り上げており，腰部は海鼠壁風の目地を切るなど特徴的な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002938"},{"id":"00002928","register_sub_id":"101","register_pk":"103918","name":"平安神宮西神庫","kana":"へいあんじんぐうにしじんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.01700573,"lng":135.78221652,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造校倉、銅板葺、建築面積13㎡","structure_material":"木造校倉","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0118","desc":"東神庫と対をなす神庫。本殿の背後，透塀内の西北隅に位置し，形式・規模・意匠ともに東神庫と厳密な対称型をなす。正面には両開き板扉を設け，軒は一軒疎垂木である。比較的小規模ではあるが，校倉建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002928"},{"id":"00002934","register_sub_id":"101","register_pk":"103924","name":"平安神宮西門及び西外廻廊","kana":"へいあんじんぐうにしもんおよびにしかいろう","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01535155,"lng":135.78175344,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0124","desc":"昭和１５年の一連の造営時に建設されたもの。南歩廊から神門翼廊までを矩折れに結び，中程には章善門とも称する西門を開く。東門・東外廻廊と完全な対称型をなし，両者で龍尾壇下の南内庭を区画する。広大な境内空間の街路側に位置し，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002934"},{"id":"00002937","register_sub_id":"101","register_pk":"103927","name":"平安神宮東祭器庫","kana":"へいあんじんぐうひがしさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01571752,"lng":135.78146434,"geo_status":"db","era":"明治40／昭和15移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0127","desc":"西外廻廊の西に位置する土蔵造２階建の祭器庫。正面入口には切妻造瓦葺の屋根をかけ，寄棟造の小屋はトラスを組む。外壁は腰部を板張りとする特徴的な外観である。昭和１５年の一連の造営時に，旧位置から移築されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002937"},{"id":"00002927","register_sub_id":"101","register_pk":"103917","name":"平安神宮東神庫","kana":"へいあんじんぐうひがしじんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.01701841,"lng":135.78265727,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造校倉、銅板葺、建築面積13㎡","structure_material":"木造校倉","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0117","desc":"本殿の背後，透塀内の東北隅に位置し，１２尺（約３．６ｍ）四方の妻入正方形平面を持つ。屋根は切妻造，銅板葺で，正面には縁を設け，その左側に石階及び木階を備える。その殆どが丹塗の境内にあって，白木の外観が特徴的な校倉である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002927"},{"id":"00002933","register_sub_id":"101","register_pk":"103923","name":"平安神宮東門及び東外廻廊","kana":"へいあんじんぐうひがしもんおよびひがしそとかいろう","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01540213,"lng":135.78317174,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0123","desc":"南歩廊から神門翼廊までを矩折れに結び，南内庭の東側を区切る。中程には宣政門とも称する東門を開く。門は切妻造，本瓦葺，二軒半繁垂木の切妻造。廻廊は単廊式で本瓦葺，総延長約５０ｍに達する。丹塗と緑の連子窓の組合せが，境内景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002933"},{"id":"00002930","register_sub_id":"101","register_pk":"103920","name":"平安神宮南歩廊","kana":"へいあんじんぐうみなみほろう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.0162031,"lng":135.78316988,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積288㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0120","desc":"Ｌ字型平面で蒼龍楼と東外廻廊，白虎楼と西外廻廊を結ぶ歩廊。２間幅で，中央を連子窓を設けた壁で区切る。二軒の丸垂木で，屋根は本瓦葺。左右とも東西棟部中央に扉口を開く。形式・規模ともに本殿廻りの塀とは明確に区別され，境内景観を形作っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002930"},{"id":"00009783","register_sub_id":"101","register_pk":"195612","name":"本能寺表門","kana":"ほんのうじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区寺町通御池下る下本能寺前町522-1","lat":35.01037836,"lng":135.76732415,"geo_status":"db","era":"明治4／明治12移築","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造、瓦葺、間口4.9m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0428","desc":"寺町通に西面して建つ大型の薬医門で、左右に袖塀を付ける。男梁を四本架け、両端二本に蟇股、中央二本に大瓶束を載せて棟木を受ける。軒は二軒疎垂木で、垂木上面に木小舞を並べる。ケヤキの良材を使い、細部意匠や施工も上質で、気品を備えた表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009783"},{"id":"00009782","register_sub_id":"101","register_pk":"195611","name":"本能寺信長公御廟所拝殿","kana":"ほんのうじのぶながこうごびょうしょはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区寺町通御池下る下本能寺前町522-1他","lat":35.01012851,"lng":135.76853768,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0427","desc":"本堂の南東に位置する信長公廟所を拝するための建物。三間四方で、各面とも中央間を開放し、両脇間に腰板壁を張る。内法長押を廻らして柱上に舟肘木をのせ、小壁は漆喰仕上げで内部に格天井を張る。大仏様風の木鼻を用いるなど、復古的な要素を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009782"},{"id":"00009781","register_sub_id":"101","register_pk":"195610","name":"本能寺本堂","kana":"ほんのうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区寺町通御池下る下本能寺前町522-1他","lat":35.01032482,"lng":135.76830568,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積590㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0426","desc":"寺町通に向けて境内を開く。本堂は七間四方で、内陣を五間四間と広くとるなど日蓮宗系寺院本堂の標準的平面を示す。広い内陣を確保するため、側柱を立て登らせ、トラスを併用して大スパンを実現する。細部は古典に忠実で、天沼俊一の設計として初期の大型仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009781"},{"id":"00010656","register_sub_id":"101","register_pk":"201230","name":"向日神社客殿","kana":"むこうじんじゃきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市向日町南山82-1","lat":34.943787,"lng":135.697433,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0489","desc":"境内の南寄りに東面して建つ。Ｔ字形平面で屋根を入母屋造とする主体部の東正面に切妻の車寄を付ける。玄関の西奥に座敷を並べて奥の八畳に床と平書院を備え、南に廊下を通す。車寄に筬欄間を廻らし、格天井を張るなど、端正な意匠で気品のある近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010656"},{"id":"00010657","register_sub_id":"101","register_pk":"201231","name":"向日神社手水舎","kana":"むこうじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944221,"lng":135.697882,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積4.0㎡、手水鉢・井戸付","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0490","desc":"境内の東寄り、参道北方に南面して建つ。桁行を正面一間背面二間、梁間を一間とし、東面と北面のみを腰貫で固めて使用の便を図る。全体に簡素な意匠としながら、正面の虹梁形飛貫や蟇股を雲紋化した彫刻として華やかに飾り、境内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010657"},{"id":"00010645","register_sub_id":"101","register_pk":"201219","name":"向日神社幣拝殿及び本殿覆屋","kana":"むこうじんじゃへいはいでんおよびほんでんおおいや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944179,"lng":135.697169,"geo_status":"db","era":"天保13年（1842）","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積277㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0478","desc":"三間社流造の本殿を納める覆屋は方五間で、流造のような形態とし、幣殿で入母屋造の拝殿と繋ぐ。桁行五間の拝殿は柱間が広く大規模で、正面に千鳥破風と向唐破風造の向拝を付す。本殿覆屋は比較的簡素だが、拝殿向拝廻りの雲龍等の彫刻は特に濃密で目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010645"},{"id":"00010650","register_sub_id":"101","register_pk":"201224","name":"向日神社末社春日神社本殿","kana":"むこうじんじゃまっしゃかすがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944295,"lng":135.697012,"geo_status":"db","era":"江戸後期／明治11年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、こけら葺、建築面積0.55㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0483","desc":"本殿北方、祖霊社西方の覆屋内に南面して建つ。近村にあった社を明治期に合祀したもの。小規模な一間社流造で、正面に軒唐破風を付ける。身舎及び庇の組物の肘木に繰形を付け、軒唐破風妻飾などに雲紋の彫刻を付けるなど、細部まで手の込んだ装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010650"},{"id":"00010655","register_sub_id":"101","register_pk":"201229","name":"向日神社末社勝山稲荷神社拝殿","kana":"むこうじんじゃまっしゃかつやまいなりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944398,"lng":135.698075,"geo_status":"db","era":"昭和前期／昭和42年頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0488","desc":"稲荷神社本殿の南正面に南面して建つ。間口三間の入母屋造に向拝一間を付ける。側面を二間とし、中央の柱に脇障子を設けて前方に縁を廻す。隅柱に大仏様木鼻を付し、向拝では虹梁絵様を袖切のみとし、蟇股を鎌倉時代風の意匠とするなど、復古的要素を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010655"},{"id":"00010654","register_sub_id":"101","register_pk":"201228","name":"向日神社末社勝山稲荷神社本殿","kana":"むこうじんじゃまっしゃかつやまいなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944437,"lng":135.698077,"geo_status":"db","era":"大正期／昭和42年頃移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、銅板葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0487","desc":"境内の東寄り、参道北方に南面して建つ、正面一間背面二間の流造社殿。流造の通例と異なり身舎柱を角柱とし、柱上に舟肘木を置く。三方に刎高欄付の縁を廻し、正面に木階を設ける。庇は絵様付水引虹梁を架け、三斗を組み、装飾を加える。近代神社建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010654"},{"id":"00010649","register_sub_id":"101","register_pk":"201223","name":"向日神社末社五社神社本殿","kana":"むこうじんじゃまっしゃごしゃじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944248,"lng":135.697346,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0482","desc":"祖霊社の東方に南面して建つ。桁行三間梁間一間、切妻造で、正面中央間のみ広めて虹梁を架ける。正面は腰下を板壁、内法を菱格子、上部土壁とする。内部は背面寄りに片流屋根の内陣を設けて五室に間仕切り、板唐戸を吊り、繁垂木とする。独特な形式の境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010649"},{"id":"00010651","register_sub_id":"101","register_pk":"201225","name":"向日神社末社御霊神社本殿","kana":"むこうじんじゃまっしゃごりょうじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町南山82-1","lat":34.944048,"lng":135.69738,"geo_status":"db","era":"江戸中期／明治10年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積2.3㎡、覆屋付","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0484","desc":"拝殿南方に北面して建ち、正面に虹梁をもつ覆屋を架ける。一間社流見世棚造で、見世棚左右に板壁を張る。屋根はこけら葺で、木製の箱棟と鬼板を飾る。組物は柱上の舟肘木のみの簡素な形式とする。見世棚造としては比較的規模が大きく、境内の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010651"},{"id":"00010647","register_sub_id":"101","register_pk":"201221","name":"向日神社末社祖霊社本殿","kana":"むこうじんじゃまっしゃそれいしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944334,"lng":135.697155,"geo_status":"db","era":"元禄元年（1688）","year":1688,"year_source":"db","year_min":1688,"year_max":1688,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0480","desc":"拝殿北方に渡廊を介し、東面して建つ。もとは祈祷所として建立されたもので、桁行二間半梁間二間、入母屋造妻入である。組物を持たず簡素な意匠とし、外壁の白壁が目立つ瀟洒な建物で、内部の改修はあるものの、天保期の境内整備以前に遡る遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010647"},{"id":"00010648","register_sub_id":"101","register_pk":"201222","name":"向日神社末社祖霊社渡廊","kana":"むこうじんじゃまっしゃそれいしゃわたろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.94427,"lng":135.69716,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0481","desc":"本社拝殿と祖霊社本殿を南北に繋ぐ、長さ約一〇メートルの渡廊。南寄り約三メートルを落棟にし、北寄りは間柱を入れて柱上に舟肘木を据え、梁行の各柱間に虹梁を架けて蟇股で棟木を受ける。軸部はやや木太いが、太鼓状の床桁や反りのある垂木が軽快さを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010648"},{"id":"00010652","register_sub_id":"101","register_pk":"201226","name":"向日神社末社天満宮社本殿","kana":"むこうじんじゃまっしゃてんまんぐうしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944324,"lng":135.697769,"geo_status":"db","era":"天保4年（1833）","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0485","desc":"境内の東寄り、参道北方に南面して建つ。切妻造の本体前面に切妻造妻入の向拝を併設する独特の構えとなる。後端間後寄りの内陣は腰高の床張として三室に仕切り、幣軸構の板唐戸を吊る。前面に刎高欄付の縁と木階を設け、こけら葺の屋根を架けて内殿風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010652"},{"id":"00010653","register_sub_id":"101","register_pk":"201227","name":"向日神社末社天満宮社瑞垣","kana":"むこうじんじゃまっしゃてんまんぐうしゃみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944345,"lng":135.697768,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、総延長17m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0486","desc":"天満宮社本殿向拝の側面に取り付き、矩折れに後方へ延びる。基壇上の土台に立てる柱で直接棟木を受ける。腰下を竪板壁、内法は襷格子を入れ、瓦葺の屋根とする。挿肘木の腕木には大仏様の木鼻を付けるなど、簡素ながら装飾を持ち、社叢景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010653"},{"id":"00010646","register_sub_id":"101","register_pk":"201220","name":"向日神社南門・北門及び瑞垣","kana":"むこうじんじゃみなみもん・きたもんおよびみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944146,"lng":135.696969,"geo_status":"db","era":"天保13年（1842）","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"南門及び北門 木造、瓦葺、間口2.0m 瑞垣 木造、瓦葺、総延長52m","structure_material":"南門及び北門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0479","desc":"拝殿に接続して本殿覆屋の三方に瑞垣を廻らし、南北に門口を開く。瑞垣は瓦葺で腰下を竪板張、上部を菱格子とし、内側に石製の添柱を付す。南門と北門はいずれも棟門で絵様付の腕木を二段重ねる。華やかな植物紋の透彫を嵌めた桟唐戸を吊り、境内を荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010646"},{"id":"00014400","register_sub_id":"101","register_pk":"511389","name":"明覺寺山門","kana":"めいかくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99116944,"lng":135.75681389,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0650","desc":"新町通に面する山門。五平の本柱と控柱を貫２段で繋いだ薬医門で、切妻造桟瓦葺。両妻は梁上においた板蟇股が棟木を受ける。軒は１軒疎垂木で破風拝みに懸魚を付ける。間口２・６メートルで、要所に金具を打つ板戸両開を吊る。市中の寺院の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014400"},{"id":"00014398","register_sub_id":"101","register_pk":"511387","name":"明覺寺茶室杏梁庵","kana":"めいかくじちゃしつきょうりょうあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99116944,"lng":135.75711389,"geo_status":"db","era":"大正9年／昭和初期移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0648","desc":"本堂の奥に位置。観月橋にあった本願寺門主の別邸三夜荘からの移築と伝わる四畳半の茶室と、隣接する四畳水屋からなる。切妻造桟瓦葺で南に土庇を付す。茶室は半間床で網代天井は北半間を一段落とす。南に躙口、西に貴人口を開ける。大谷光瑞ゆかりの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014398"},{"id":"00014399","register_sub_id":"101","register_pk":"511388","name":"明覺寺土蔵","kana":"めいかくじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99108611,"lng":135.75710278,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0649","desc":"本堂奥、茶室南脇に位置する。土蔵造２階建、切妻造本瓦葺。腰は竪板張、上部は漆喰塗で鉢巻まで塗込める。西に庇を付し、掛子塗の土戸両開の戸口を設け、内部は１・２階とも１室。小屋は和小屋で両妻の梁が中引梁を受ける。敷地南東の茶室露地の背景を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014399"},{"id":"00014397","register_sub_id":"101","register_pk":"511386","name":"明覺寺本堂","kana":"めいかくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99114722,"lng":135.75699722,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0647","desc":"東本願寺の西に位置。桁行５間梁間７間切妻造桟瓦葺で入母屋造玄関を付す。１２畳２室の外陣と両脇に余間を配す内陣からなる変則的な平面。内陣に須弥壇を置く。左余間は襖絵を建込んだ上段の間で、次の間には杉戸絵を飾る。小規模だが格調高い設え持つ本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014397"},{"id":"00009794","register_sub_id":"101","register_pk":"195623","name":"離宮八幡宮高天宮神社","kana":"りきゅうはちまんぐうこうてんぐうじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89179554,"lng":135.67945754,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.7㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0439","desc":"境内西方に東面して建つ。三間社流造、銅板葺で、縁を廻らし、浜床を設け、妻を豕扠首とする。向拝中備は、拝殿同様に古式な蟇股を翻案した独自の意匠の蟇股を飾る。全体的に装飾を控え、復古的に簡素な意匠を見せることで格調のある趣きとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009794"},{"id":"00009797","register_sub_id":"101","register_pk":"195626","name":"離宮八幡宮透塀","kana":"りきゅうはちまんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89190833,"lng":135.67951037,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、延長38m、潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0442","desc":"本殿の側背面にコ字形に配された透塀で、側面六間、背面八間とし、前端は拝殿釣殿端部に取付く。基壇上に建ち、腰までを羽目板、腰長押と内法長押で軸を固め、菱格子をはめる。軒は疎垂木で、屋根は銅板葺とする。簡素な意匠ながら、格調高い結界装置である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009797"},{"id":"00009795","register_sub_id":"101","register_pk":"195624","name":"離宮八幡宮中門","kana":"りきゅうはちまんぐうちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89167419,"lng":135.6795789,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0440","desc":"拝殿正面に位置し、本殿、拝殿、中門を一直線に並べる。四脚門形式で左右に矩折に袖塀を付属する。本柱、控柱とも角柱で、両開の桟唐戸を吊る。軒は二軒で優美な反りをもたせる。妻に板蟇股を配し、正面蟇股には東福寺月下門の意匠を引用し、外観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009795"},{"id":"00009796","register_sub_id":"101","register_pk":"195625","name":"離宮八幡宮手水所","kana":"りきゅうはちまんぐうてみずしょ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89155283,"lng":135.67953035,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、瓦葺、面積3.1㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0441","desc":"中門の南西に南北棟で建つ。切妻造桟瓦葺で、二本の丸柱の前後に控柱をたて、柱上に渡した男梁で桁を受け、屋根を支える。両妻には板蟇股をおいて棟木を受ける。懸魚や蟇股の意匠は境内の他の建物と共通し、復古的な意匠を持つ。洗練された境内景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009796"},{"id":"00009793","register_sub_id":"101","register_pk":"195622","name":"離宮八幡宮拝殿","kana":"りきゅうはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89176556,"lng":135.67954749,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0438","desc":"桁行三間梁間二間、入母屋造の主体部正面に唐破風造の向拝を付け、両側面後寄りに桁行二間の翼廊、背面中央に幣殿を設ける。柱上に舟肘木をおき、軒は二軒疎垂木とする。主体部は折上格天井を張り、ほかは化粧屋根裏である。木割が太く、復古的な設計法を採る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009793"},{"id":"00009792","register_sub_id":"101","register_pk":"195621","name":"離宮八幡宮本殿","kana":"りきゅうはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89187121,"lng":135.67951608,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0437","desc":"西国街道に面して境内を構える。本殿は、三間社流造、銅板葺で、三方に縁を廻らし、背面柱筋に脇障子をたてる。身舎は内外陣に二分し、内陣前面に板唐戸三所を開き、外陣正面を吹き放つ。蟇股や木鼻の細部を含め、全体を中世風の復古的な意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009792"},{"id":"00013136","register_sub_id":"101","register_pk":"368381","name":"蓮乗寺山門","kana":"れんじょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27935,"lng":135.512575,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0593","desc":"敷地南辺中央東寄りに南面して建つ。切妻造桟瓦葺の薬医門で、親柱に五平材を用いた正面側は簡素なつくりとする一方で、側面の梁上には大振りの絵様付蟇股を置き、控柱を絵様、木鼻付の虹梁状の飛貫を抜き通して蟇股で桁を支える。境内の表構を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013136"},{"id":"00013135","register_sub_id":"101","register_pk":"368380","name":"蓮乗寺鐘楼","kana":"れんじょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27933611,"lng":135.51262778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積5.2㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0592","desc":"境内南東に北面して建つ。切妻造桟瓦葺、軒は一軒疎垂木とし、妻に懸魚を飾る。礎石の上に角柱を内転びで立て、二段に通した貫で固めて四周に腰板を張る。棟木下に湾曲した鐘釣梁を渡し、梵鐘を吊る。簡素ながら山門と並び立ち、境内の表構を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013135"},{"id":"00013134","register_sub_id":"101","register_pk":"368379","name":"蓮乗寺番神堂","kana":"れんじょうじばんじんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27938333,"lng":135.51246389,"geo_status":"db","era":"文政11年（1828）","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0591","desc":"境内南西に北面して建つ。入母屋造桟瓦葺、正側面に縁を廻し、正面一間向拝付。内部は外陣は棹縁天井の床畳敷で、内陣は側面化粧軒裏、中央一段高く棹縁天井とし、床板敷。内陣中央に来迎壁と須弥壇を置き、背後に五連の神棚を並べ、番神信仰の有様を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013134"},{"id":"00013133","register_sub_id":"101","register_pk":"368378","name":"蓮乗寺本堂","kana":"れんじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27956667,"lng":135.51255833,"geo_status":"db","era":"寛政11年（1799）／昭和30年代・平成28年改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積249㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0590","desc":"美山町西部にある日蓮宗寺院。敷地中央に南面して建つ入母屋造の本堂は、内部西を仏堂、東を庫裏とし、正面中央東寄に式台玄関を設ける。仏堂は六間取の方丈形式で、正面と西側に縁を廻す。奥側中央の仏間奥には位牌堂が突出する。境内景観の中核を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013133"},{"id":"00014409","register_sub_id":"101","register_pk":"511398","name":"天日名鳥命神社幣拝殿","kana":"あめのひなどりのみことじんじゃへいはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市大畑874","lat":35.48755278,"lng":134.11855278,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"31 - 0282","desc":"丘上の式内社の幣拝殿。入母屋造妻入桟瓦葺、正面に入母屋造起り破風の向拝を設け、妻飾懸魚を重ねる。向拝に格天井、縁を三方に廻し、内部一室、背面に切妻造の幣殿を張り出す。原寸図が遺る懸魚は本殿彫刻に比べて伝統的な意匠で、境内の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014409"},{"id":"00014408","register_sub_id":"101","register_pk":"511397","name":"天日名鳥命神社本殿","kana":"あめのひなどりのみことじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市大畑874","lat":35.48753611,"lng":134.11848333,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"31 - 0281","desc":"鹿野城下から鳥取城下への道沿い丘上に所在する式内社。一間社流造銅板葺の床が高い本殿で、四方に縁を廻す。亀腹は石造。全体に装飾は抑制的だが、蟇股等彫刻意匠に近代的な華やかさがある。正面扉に神紋を付す。設計書を備え近代の社殿造営の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014408"},{"id":"00014927","register_sub_id":"101","register_pk":"519187","name":"宇倍神社神門","kana":"うべじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48080833,"lng":134.26900833,"geo_status":"db","era":"大正4年／昭和前期改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、檜皮葺、間口3.0m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0286","desc":"拝殿の東に位置する切妻造檜皮葺の門。円柱の本柱と角柱の控柱を腰貫、内法貫で固め、組物は舟肘木、中備には菊紋の上半部を呈す彫刻を配す。豕扠首で棟木を支え、軒は一軒繁垂木。かつて紙幣の図柄となった門で優美な起り屋根が宇部神社の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014927"},{"id":"00014926","register_sub_id":"101","register_pk":"519186","name":"宇倍神社透塀","kana":"うべじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48096111,"lng":134.2687,"geo_status":"db","era":"大正11年／昭和前期・同48年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、銅板葺、延長61m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0285","desc":"幣殿両脇から後方に延びて本殿を囲う透塀。切石積基壇に土台を置いて柱を１間毎に立て、軒桁は腕木で支持し屋根銅板葺とする。各柱間には連子窓を入れ、腰は縦板目板張とし、正面両脇に出入口を設ける。本殿と一体となって境内の歴史的な景観をつくる透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014926"},{"id":"00014925","register_sub_id":"101","register_pk":"519185","name":"宇倍神社拝殿","kana":"うべじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48086667,"lng":134.26889722,"geo_status":"db","era":"明治17年／平成11年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0284","desc":"本殿の東方に位置する拝殿は入母屋造妻入檜皮葺。正面に木階を付し、四周に高欄付縁を廻らす。組物は舟肘木とし、軒は二軒繁垂木、妻飾は木連格子。内部は一室の拭板敷で、格天井を張る。破風板など錺金具で荘厳する以外は全体に装飾抑えた端正な意匠の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014925"}];
